/* DAWAH X — ahmad, অধ্যায় 38 · খণ্ড 38 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][38]=[[7401,7401,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَنَعَ لِأَحَدِكُمْ خَادِمُهُ طَعَامَهُ ثُمَّ جَاءَ بِهِ قَدْ ‏ ‏وَلِيَ ‏ ‏حَرَّهُ ‏ ‏وَدُخَانَهُ ‏ ‏فَلْيُقْعِدْهُ مَعَهُ فَلْيَأْكُلْ فَإِنْ كَانَ الطَّعَامُ ‏ ‏مَشْفُوفًا ‏ ‏قَلِيلًا فَلْيَضَعْ فِي يَدِهِ أُكْلَةً أَوْ أُكْلَتَيْنِ ‏","","",""],[7402,7402,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحَاسَدُوا وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا تَبَاغَضُوا وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا يَبِعْ أَحَدُكُمْ عَلَى بَيْعِ أَخِيهِ وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَخْذُلُهُ وَلَا يَحْقِرُهُ التَّقْوَى هَاهُنَا وَأَشَارَ بِيَدِهِ إِلَى صَدْرِهِ ثَلَاثَ مَرَّاتٍ حَسْبُ امْرِئٍ مُسْلِمٍ مِنْ الشَّرِّ أَنْ يَحْقِرَ أَخَاهُ الْمُسْلِمَ كُلُّ الْمُسْلِمِ عَلَى الْمُسْلِمِ حَرَامٌ دَمُهُ وَمَالُهُ وَعِرْضُهُ ‏","","",""],[7403,7403,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَمَّوْا بِي وَلَا تَكَنَّوْا بِكُنْيَتِي أَنَا ‏ ‏أَبُو الْقَاسِمِ ‏","","",""],[7404,7404,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أَدُلُّكُمْ عَلَى مَا يُكَفِّرُ اللَّهُ بِهِ الْخَطَايَا وَيَرْفَعُ بِهِ الدَّرَجَاتِ الْخُطَى إِلَى الْمَسَاجِدِ وَإِسْبَاغُ الْوُضُوءِ عِنْدَ ‏ ‏الْمَكَارِهِ ‏ ‏وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ فَذَلِكَ ‏ ‏الرِّبَاطُ ‏","","",""],[7405,7405,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأَ أَحَدُكُمْ ‏ ‏فَلْيَسْتَنْثِرْ ‏ ‏وَإِذَا ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ ‏","","",""],[7406,7406,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنِي ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ ‏ ‏وِتْرٌ ‏ ‏يُحِبُّ ‏ ‏الْوِتْرَ ‏","","",""],[7407,7407,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ ‏ ‏وَتْرٌ ‏ ‏يُحِبُّ ‏ ‏الْوَتْرَ ‏","","",""],[7408,7408,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏هَذَا خَيْرٌ مِنْ أَلْفِ صَلَاةٍ فِي غَيْرِهِ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏","","",""],[7409,7409,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏خَيْرٌ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْمَسْجِدَ الْحَرَامَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَاهُ ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏فَذَكَرَ حَدِيثًا ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرَهُ وَلَمْ يَشُكَّ ‏","","",""],[7410,7410,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُشَدُّ الرِّحَالُ إِلَّا لِثَلَاثَةِ مَسَاجِدَ ‏ ‏مَسْجِدِ الْحَرَامِ ‏ ‏وَمَسْجِدِي ‏ ‏هَذَا ‏ ‏وَالْمَسْجِدِ الْأَقْصَى ‏","","",""],[7411,7411,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجُلٍ يَسُوقُ بَدَنَةً قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا بَدَنَةٌ قَالَ ارْكَبْهَا ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَلَقَدْ رَأَيْتُهُ يُسَايِرُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِي عُنُقِهَا نَعْلٌ ‏","","",""],[7412,7412,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي النِّدَاءِ وَالصَّفِّ الْأَوَّلِ ‏ ‏لَاسْتَهَمُوا ‏ ‏عَلَيْهِمَا وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏التَّهْجِيرِ ‏ ‏لَاسْتَبَقُوا إِلَيْهِ وَلَوْ يَعْلَمُونَ مَا فِي ‏ ‏الْعَتَمَةِ ‏ ‏وَالصُّبْحِ لَأَتَوْهُمَا وَلَوْ حَبْوًا ‏ ‏فَقُلْتُ ‏ ‏لِمَالِكٍ ‏ ‏أَمَا يُكْرَهُ أَنْ يَقُولَ ‏ ‏الْعَتَمَةَ ‏ ‏قَالَ ‏ ‏هَكَذَا قَالَ الَّذِي حَدَّثَنِي ‏","","",""],[7413,7413,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏مَسْجِدِي ‏ ‏خَيْرٌ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ مِنْ الْمَسَاجِدِ إِلَّا ‏ ‏الْمَسْجِدَ الْأَقْصَى ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏فَذَكَرَ حَدِيثًا ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَعَنْ ‏ ‏عَائِشَةَ ‏ ‏فَذَكَرَهُ وَلَمْ يَشُكَّ ‏","","",""],[7414,7414,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ ‏ ‏الصَّدَقَةِ ‏ ‏مَا كَانَ عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏ ‏وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى ‏ ‏قُلْتُ ‏ ‏لِأَيُّوبَ ‏ ‏مَا عَنْ ‏ ‏ظَهْرِ غِنًى ‏ ‏قَالَ ‏ ‏عَنْ فَضْلِ غِنَاكَ ‏","","",""],[7415,7415,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْخَيْرِ سَبْعِينَ سَنَةً فَإِذَا أَوْصَى حَافَ فِي وَصِيَّتِهِ فَيُخْتَمُ لَهُ بِشَرِّ عَمَلِهِ فَيَدْخُلُ النَّارَ وَإِنَّ الرَّجُلَ لَيَعْمَلُ بِعَمَلِ أَهْلِ الشَّرِّ سَبْعِينَ سَنَةً فَيَعْدِلُ فِي وَصِيَّتِهِ فَيُخْتَمُ لَهُ بِخَيْرِ عَمَلِهِ فَيَدْخُلُ الْجَنَّةَ ‏ ‏قَالَ ‏ ‏ثُمَّ يَقُولُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَاقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏تِلْكَ حُدُودُ اللَّهِ ‏ ‏إِلَى قَوْلِهِ ‏ ‏عَذَابٌ مُهِينٌ ‏}","","",""],[7416,7416,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏اسْتَلْجَجَ ‏ ‏أَحَدُكُمْ بِالْيَمِينِ فِي أَهْلِهِ فَإِنَّهُ ‏ ‏آثَمُ ‏ ‏لَهُ عِنْدَ اللَّهِ مِنْ الْكَفَّارَةِ الَّتِي أُمِرَ بِهَا ‏","","",""],[7417,7417,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَأْتِي عَلَيْكُمْ زَمَانٌ يُخَيَّرُ فِيهِ الرَّجُلُ بَيْنَ الْعَجْزِ وَالْفُجُورِ فَمَنْ أَدْرَكَ ذَلِكَ الزَّمَانَ فَلْيَخْتَرْ الْعَجْزَ عَلَى الْفُجُورِ ‏","","",""],[7418,7418,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏أَخْبَرَنَا ‏ ‏مِينَاءُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ الْعَنْ ‏ ‏حِمْيَرَ ‏ ‏فَأَعْرَضَ عَنْهُ ثُمَّ جَاءَهُ مِنْ نَاحِيَةٍ أُخْرَى فَأَعْرَضَ عَنْهُ وَهُوَ يَقُولُ الْعَنْ ‏ ‏حِمْيَرَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَحِمَ اللَّهُ ‏ ‏حِمْيَرَ ‏ ‏أَفْوَاهُهُمْ سَلَامٌ وَأَيْدِيهِمْ طَعَامٌ أَهْلُ أَمْنٍ وَإِيمَانٍ ‏","","",""],[7419,7419,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَوَضَّأَ أَحَدُكُمْ فَلْيَجْعَلْ فِي أَنْفِهِ ثُمَّ ‏ ‏لِيَسْتَنْثِرْ ‏ ‏وَمَنْ ‏ ‏اسْتَجْمَرَ ‏ ‏فَلْيُوتِرْ ‏","","",""],[7420,7420,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُثَنَّى بْنُ الصَّبَّاحِ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ شُعَيْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَكُونُ فِي الرَّمْلِ أَرْبَعَةَ أَشْهُرٍ ‏ ‏أَوْ خَمْسَةَ أَشْهُرٍ ‏ ‏فَيَكُونُ فِينَا النُّفَسَاءُ وَالْحَائِضُ ‏ ‏وَالْجُنُبُ ‏ ‏فَمَا ‏ ‏تَرَى قَالَ ‏ ‏عَلَيْكَ بِالتُّرَابِ ‏","","",""],[7421,7421,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ مِنْ اللَّيْلِ فَلْيَسْتَفْتِحْ صَلَاتَهُ بِرَكْعَتَيْنِ خَفِيفَتَيْنِ ‏","","",""],[7422,7422,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ دُعِيَ فَلْيُجِبْ فَإِنْ كَانَ مُفْطِرًا أَكَلَ وَإِنْ كَانَ صَائِمًا فَلْيُصَلِّ وَلْيَدْعُ لَهُمْ ‏","","",""],[7423,7423,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏الْفَأْرَةُ مَمْسُوخَةٌ بِآيَةِ أَنَّهُ يُقَرَّبُ لَهَا لَبَنُ ‏ ‏اللِّقَاحِ ‏ ‏فَلَا تَذُوقُهُ وَيُقَرَّبُ لَهَا لَبَنُ الْغَنَمِ فَتَشْرَبُهُ ‏ ‏أَوْ قَالَ فَتَأْكُلُهُ ‏ ‏فَقَالَ لَهُ ‏ ‏كَعْبٌ ‏ ‏أَشَيْءٌ سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَفَنَزَلَتْ التَّوْرَاةُ عَلَيَّ ‏","","",""],[7424,7424,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏فَرَعَ ‏ ‏وَلَا ‏ ‏عَتِيرَةَ ‏ ‏وَالْفَرَعُ ‏ ‏أَوَّلُ النِّتَاجِ كَانَ يُنْتَجُ لَهُمْ فَيَذْبَحُونَهُ ‏","","",""],[7425,7425,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالنَّقِيرِ ‏","","",""],[7426,7426,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو كَثِيرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَمْرُ مِنْ هَاتَيْنِ الشَّجَرَتَيْنِ النَّخْلَةِ وَالْعِنَبَةِ ‏","","",""],[7427,7427,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بَيْنَ ‏ ‏لَابَتَيْ ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَلَوْ وَجَدْتُ ‏ ‏الظِّبَاءَ ‏ ‏مَا بَيْنَ ‏ ‏لَابَتَيْهَا ‏ ‏مَا ذَعَرْتُهَا وَجَعَلَ حَوْلَ ‏ ‏الْمَدِينَةِ ‏ ‏اثْنَيْ عَشَرَ مِيلًا حِمًى ‏","","",""],[7428,7428,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ يَحْيَى بْنِ عُمَارَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏الْقَرَّاظَ ‏ ‏وَكَانَ مِنْ أَصْحَابِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يَزْعُمُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَرَادَ أَهْلَهَا بِسُوءٍ ‏ ‏يَعْنِي ‏ ‏الْمَدِينَةَ ‏ ‏أَذَابَهُ اللَّهُ كَمَا يَذُوبُ الْمِلْحُ فِي الْمَاءِ ‏","","",""],[7429,7429,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ لَهُ مَالٌ فَلَمْ يُؤَدِّ حَقَّهُ جُعِلَ يَوْمَ الْقِيَامَةِ ‏ ‏شُجَاعٌ ‏ ‏أَقْرَعُ لَهُ ‏ ‏زَبِيبَتَانِ ‏ ‏يَتْبَعُهُ حَتَّى يَضَعَ يَدَهُ فِي ‏ ‏فِيهِ فَلَا يَزَالُ ‏ ‏يَقْضِمُهَا ‏ ‏حَتَّى ‏ ‏يُقْضَى بَيْنَ الْعِبَادِ ‏","","",""],[7430,7430,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَابْنُ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ عَلَى الْمُؤْمِنِ فِي عَبْدِهِ وَلَا فَرَسِهِ ‏ ‏صَدَقَةٌ ‏","","",""],[7431,7431,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقْسِمُ تَمْرًا مِنْ تَمْرِ ‏ ‏الصَّدَقَةِ ‏ ‏وَالْحَسَنُ بْنُ عَلِيٍّ ‏ ‏فِي حِجْرِهِ فَلَمَّا فَرَغَ حَمَلَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏عَاتِقِهِ ‏ ‏فَسَالَ لُعَابُهُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَفَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ فَإِذَا ‏ ‏تَمْرَةٌ ‏ ‏فِي ‏ ‏فِيهِ ‏ ‏فَأَدْخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ فَانْتَزَعَهَا مِنْهُ ثُمَّ قَالَ ‏ ‏أَمَا عَلِمْتَ أَنَّ ‏ ‏الصَّدَقَةَ ‏ ‏لَا تَحِلُّ لِآلِ ‏ ‏مُحَمَّدٍ ‏","","",""],[7432,7432,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُسْتَأْمَرُ ‏ ‏الثَّيِّبُ ‏ ‏وَتُسْتَأْذَنُ ‏ ‏الْبِكْرُ ‏ ‏قَالُوا وَمَا إِذْنُهَا يَا رَسُولَ اللَّهِ قَالَ تَسْكُتُ ‏","","",""],[7433,7433,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏كَذَا ‏ ‏قَالَ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ وَذَكَرَ حَدِيثَ ‏ ‏الْفَزَارِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ وَلَدَتْ امْرَأَتِي غُلَامًا أَسْوَدَ وَهُوَ حِينَئِذٍ يُعَرِّضُ بِأَنْ يَنْفِيَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَكَ إِبِلٌ قَالَ نَعَمْ قَالَ مَا أَلْوَانُهَا قَالَ حُمْرٌ قَالَ أَفِيهَا ‏ ‏أَوْرَقُ ‏ ‏قَالَ نَعَمْ فِيهَا ذَوْدٌ ‏ ‏وُرْقٌ ‏ ‏قَالَ مِمَّ ذَاكَ ‏ ‏تَرَى قَالَ مَا أَدْرِي لَعَلَّهُ أَنْ يَكُونَ نَزَعَهَا ‏ ‏عِرْقٌ ‏ ‏قَالَ وَهَذَا ‏ ‏لَعَلَّهُ أَنْ يَكُونَ نَزَعَهُ ‏ ‏عِرْقٌ ‏ ‏وَلَمْ يُرَخِّصْ لَهُ فِي ‏ ‏الِانْتِفَاءِ ‏ ‏مِنْهُ ‏","","",""],[7434,7434,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنَا ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏مُزَيْنَةَ ‏ ‏وَنَحْنُ عِنْدَ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجَمَ ‏ ‏يَهُودِيًّا وَيَهُودِيَّةً ‏","","",""],[7435,7435,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فَاجْلِدُوهُ ثُمَّ إِذَا شَرِبَ فَاجْلِدُوهُ ثُمَّ إِذَا شَرِبَ فَاجْلِدُوهُ ثُمَّ إِذَا شَرِبَ فِي الرَّابِعَةِ فَاقْتُلُوهُ ‏","","",""],[7436,7436,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏","","",""],[7437,7437,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَمَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا قُلْتَ لِصَاحِبِكَ وَالْإِمَامُ يَخْطُبُ أَنْصِتْ فَقَدْ ‏ ‏لَغَوْتَ ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَأَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[7438,7438,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَدْرَكَ مِنْ الصَّلَاةِ رَكْعَةً فَقَدْ أَدْرَكَ الصَّلَاةَ ‏","","",""],[7439,7439,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏الْأَغَرُّ أَبُو عَبْدِ اللَّهِ ‏ ‏صَاحِبُ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ يَوْمُ الْجُمُعَةِ جَلَسَتْ الْمَلَائِكَةُ عَلَى أَبْوَابِ الْمَسْجِدِ يَكْتُبُونَ كُلَّ مَنْ جَاءَ إِلَى الْجُمُعَةِ فَإِذَا خَرَجَ الْإِمَامُ ‏ ‏طَوَتْ ‏ ‏الْمَلَائِكَةُ الصُّحُفَ وَدَخَلَتْ تَسْمَعُ الذِّكْرَ ‏","","",""],[7440,7440,"","","‏ ‏قَالَ ‏ ‏وَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُهَجِّرُ ‏ ‏إِلَى الْجُمُعَةِ كَالْمُهْدِي ‏ ‏بَدَنَةً ‏ ‏ثُمَّ كَالْمُهْدِي بَقَرَةً ثُمَّ كَالْمُهْدِي شَاةً ثُمَّ كَالْمُهْدِي دَجَاجَةً ثُمَّ كَالْمُهْدِي ‏ ‏حَسِبْتُهُ قَالَ بَيْضَةً ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏أَبُو عَبْدِ اللَّهِ الْأَغَرُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ يَوْمُ الْجُمُعَةِ كَانَ عَلَى كُلِّ بَابٍ فَذَكَرَهُ وَلَمْ يَشُكَّ فِي الْبَيْضَةِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْأَغَرِّ ‏ ‏نَحْوَهُ ‏","","",""],[7441,7441,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏إِنَّ فِي الْجُمُعَةِ سَاعَةً وَأَشَارَ بِكَفِّهِ كَأَنَّهُ يُقَلِّلُهَا لَا ‏ ‏يُوَافِقُهَا ‏ ‏عَبْدٌ مُسْلِمٌ يَسْأَلُ اللَّهَ شَيْئًا إِلَّا أَعْطَاهُ إِيَّاهُ ‏","","",""],[7442,7442,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ يُقَالُ لَهُ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ غَسَّلَ مَيِّتًا فَلْيَغْتَسِلْ ‏","","",""],[7443,7443,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي لَيْثٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ غَسَّلَ مَيِّتًا فَلْيَغْتَسِلْ ‏","","",""],[7444,7444,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَا أَعْلَمُهُ إِلَّا رَفَعَ الْحَدِيثَ قَالَ ‏ ‏أَسْرِعُوا بِجَنَائِزِكُمْ فَإِنْ كَانَتْ صَالِحَةً عَجَّلْتُمُوهَا إِلَى الْخَيْرِ وَإِنْ كَانَتْ ‏ ‏طَالِحَةً ‏ ‏اسْتَرَحْتُمْ مِنْهَا وَوَضَعْتُمُوهَا عَنْ رِقَابِكُمْ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي حَفْصَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَخَالَفَهُمَا ‏ ‏يُونُسُ ‏ ‏وَقَالَ حَدَّثَنِي ‏ ‏أَبُو أُمَامَةَ بْنُ سَهْلٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏","","",""],[7445,7445,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏وَمَنْ انْتَظَرَهَا حَتَّى تُوضَعَ فِي ‏ ‏اللَّحْدِ ‏ ‏فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏وَالْقِيرَاطَانِ ‏ ‏مِثْلُ الْجَبَلَيْنِ الْعَظِيمَيْنِ ‏","","",""],[7446,7446,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَعَى ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّجَاشِيَّ ‏ ‏لِأَصْحَابِهِ وَهُوَ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَصَفُّوا خَلْفَهُ ‏ ‏وَصَلَّى عَلَيْهِ وَكَبَّرَ أَرْبَعًا ‏","","",""],[7447,7447,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كَانَ يَسْجُدُ فِيهَا قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْجُدُ فِيهَا ‏ ‏يَعْنِي ‏ ‏إِذَا السَّمَاءُ انْشَقَّتْ ‏","","",""],[7448,7448,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏أَوْ عَنْ أَحَدِهِمَا ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَيْتُمْ الْهِلَالَ فَصُومُوا وَإِذَا رَأَيْتُمُوهُ فَأَفْطِرُوا فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَصُومُوا ثَلَاثِينَ يَوْمًا ‏","","",""],[7449,7449,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُتَعَجَّلَ شَهْرُ رَمَضَانَ بِصَوْمِ يَوْمٍ أَوْ يَوْمَيْنِ إِلَّا رَجُلٌ كَانَ يَصُومُ صِيَامًا ‏ ‏فَيَأْتِي ذَلِكَ عَلَى صِيَامِهِ ‏","","",""],[7450,7450,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي أُنَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ شَهْرُ رَمَضَانَ فُتِّحَتْ أَبْوَابُ الرَّحْمَةِ وَغُلِّقَتْ أَبْوَابُ جَهَنَّمَ وَسُلْسِلَتْ الشَّيَاطِينُ ‏","","",""],[7451,7451,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَبِي أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ رَمَضَانُ فُتِّحَتْ أَبْوَابُ الرَّحْمَةِ وَغُلِّقَتْ أَبْوَابُ جَهَنَّمَ وَسُلْسِلَتْ الشَّيَاطِينُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَاه ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ ‏ ‏ذُكِرَ ‏ ‏أَنَّ ‏ ‏ابْنَ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ أَبِي أَنَسٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَلَمْ يَقُلْ عَنْ أَبِيهِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَاه ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي أَنَسٍ ‏ ‏فَذَكَرَهُ ‏","","",""],[7452,7452,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَعَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَعْتَكِفُ ‏ ‏الْعَشْرَ الْأَوَاخِرَ مِنْ رَمَضَانَ حَتَّى قَبَضَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[7453,7453,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هَلَكْتُ يَا رَسُولَ اللَّهِ قَالَ وَمَا ذَاكَ قَالَ ‏ ‏وَاقَعْتُ ‏ ‏أَهْلِي فِي رَمَضَانَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَجِدُ رَقَبَةً قَالَ لَا قَالَ أَتَسْتَطِيعُ أَنْ تَصُومَ شَهْرَيْنِ مُتَتَابِعَيْنِ قَالَ لَا يَا رَسُولَ اللَّهِ قَالَ أَفَلَا تُطْعِمُ سِتِّينَ مِسْكِينًا قَالَ لَا أَجِدُ يَا رَسُولَ اللَّهِ قَالَ فَأُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرْقٍ ‏ ‏وَالْعَرْقُ ‏ ‏الْمِكْتَلُ ‏ ‏فِيهِ تَمْرٌ قَالَ اذْهَبْ فَتَصَدَّقْ بِهَا فَقَالَ عَلَى أَفْقَرَ مِنِّي وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا بَيْنَ ‏ ‏لَابَتَيْهَا ‏ ‏أَهْلُ بَيْتٍ أَحْوَجُ إِلَيْهِ مِنَّا فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ اذْهَبْ بِهِ إِلَى أَهْلِكَ ‏","","",""],[7454,7454,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُوَاصِلُوا ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ إِنِّي لَسْتُ مِثْلَكُمْ إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي وَيَسْقِينِي قَالَ فَلَمْ يَنْتَهُوا عَنْ ‏ ‏الْوِصَالِ ‏ ‏فَوَاصَلَ ‏ ‏بِهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَيْنِ وَلَيْلَتَيْنِ ثُمَّ رَأَوْا الْهِلَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ تَأَخَّرَ الْهِلَالُ لَزِدْتُكُمْ ‏ ‏كَالْمُنَكِّلِ ‏ ‏بِهِمْ ‏","","",""],[7455,7455,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرَغِّبُ فِي قِيَامِ رَمَضَانَ مِنْ غَيْرِ أَنْ يَأْمُرَهُمْ بِعَزِيمَةٍ فَيَقُولُ ‏ ‏مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[7456,7456,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏كُلُّ عَمَلِ ابْنِ ‏ ‏آدَمَ ‏ ‏لَهُ إِلَّا الصِّيَامَ الصِّيَامُ لِي وَأَنَا أَجْزِي بِهِ ‏ ‏وَلَخُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ ‏","","",""],[7457,7457,"","","‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَأَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ ‏ ‏أُسْرِيَ ‏ ‏بِهِ لَقِيتُ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَنَعَتَهُ ‏ ‏قَالَ رَجُلٌ قَالَ حَسِبْتُهُ قَالَ ‏ ‏مُضْطَرِبٌ ‏ ‏رَجِلُ ‏ ‏الرَّأْسِ كَأَنَّهُ مِنْ رِجَالِ ‏ ‏شَنُوءَةَ ‏ ‏قَالَ وَلَقِيتُ ‏ ‏عِيسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَنَعَتَهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَبْعَةٌ أَحْمَرُ كَأَنَّهُ أُخْرِجَ مِنْ ‏ ‏دِيمَاسٍ ‏ ‏يَعْنِي حَمَّامًا ‏ ‏قَالَ وَرَأَيْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَأَنَا أَشْبَهُ وَلَدِهِ بِهِ قَالَ فَأُتِيتُ بِإِنَاءَيْنِ أَحَدُهُمَا فِيهِ لَبَنٌ وَفِي الْآخَرِ خَمْرٌ فَقَالَ لِي خُذْ أَيَّهُمَا شِئْتَ فَأَخَذْتُ اللَّبَنَ فَشَرِبْتُهُ فَقِيلَ لِي هُدِيتَ الْفِطْرَةَ وَأَصَبْتَ الْفِطْرَةَ أَمَا إِنَّكَ لَوْ أَخَذْتَ الْخَمْرَ غَوَتْ أُمَّتُكَ ‏","","",""],[7458,7458,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏هِشَامَ بْنَ حَسَّانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَسَأَلَهُ رَجُلٌ عَنْ شَيْءٍ لَمْ أَدْرِ مَا هُوَ قَالَ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏اللَّهُ أَكْبَرُ سَأَلَ عَنْهَا اثْنَانِ وَهَذَا الثَّالِثُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ رِجَالًا سَتَرْتَفِعُ بِهِمْ الْمَسْأَلَةُ حَتَّى يَقُولُوا اللَّهُ خَلَقَ الْخَلْقَ فَمَنْ خَلَقَهُ ‏","","",""],[7459,7459,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَيْلٌ ‏ ‏لِلْعَقِبِ ‏ ‏مِنْ النَّارِ ‏","","",""],[7460,7460,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَنْزِلُ رَبُّنَا عَزَّ وَجَلَّ كُلَّ لَيْلَةٍ إِذَا مَضَى ثُلُثُ اللَّيْلِ الْأَوَّلِ فَيَقُولُ ‏ ‏أَنَا الْمَلِكُ مَنْ ذَا الَّذِي يَسْأَلُنِي فَأُعْطِيَهُ مَنْ ذَا الَّذِي يَدْعُونِي فَأَسْتَجِيبَ لَهُ مَنْ ذَا الَّذِي يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ فَلَا يَزَالُ كَذَلِكَ إِلَى الْفَجْرِ ‏","","",""],[7461,7461,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَسْتَغْفِرُ اللَّهَ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةً وَأَتُوبُ إِلَيْهِ ‏","","",""],[7462,7462,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَتَى مِنْكُمْ الصَّلَاةَ فَلْيَأْتِهَا بِوَقَارٍ وَسَكِينَةٍ فَلْيُصَلِّ مَا أَدْرَكَ وَلْيَقْضِ مَا سَبَقَهُ ‏","","",""],[7463,7463,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ مَوْلُودٍ وُلِدَ عَلَى ‏ ‏الْفِطْرَةِ ‏ ‏فَأَبَوَاهُ يُهَوِّدَانِهِ وَيُنَصِّرَانِهِ مِثْلَ الْأَنْعَامِ ‏ ‏تُنْتَجُ ‏ ‏صِحَاحًا فَتُكْوَى آذَانُهَا ‏","","",""],[7464,7464,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَتَكُونُ ‏ ‏فِتَنٌ ‏ ‏الْقَاعِدُ فِيهَا خَيْرٌ مِنْ الْقَائِمِ وَالْقَائِمُ خَيْرٌ مِنْ الْمَاشِي وَالْمَاشِي خَيْرٌ مِنْ السَّاعِي وَمَنْ وَجَدَ ‏ ‏مَلْجَأً ‏ ‏أَوْ ‏ ‏مَعَاذًا ‏ ‏فَلْيَعُذْ بِهِ ‏","","",""],[7465,7465,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏تَكُونُ فِتْنَةٌ لَمْ رَفَعَهُ قَالَ ‏ ‏مَنْ وَجَدَ مَلْجَأً ‏ ‏أَوْ مَعَاذًا ‏ ‏فَلْيَعُذْ بِهِ ‏","","",""],[7466,7466,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏ابْنِ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ مَنْ أَدْرَكَ مِنْ الْعَصْرِ رَكْعَةً قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَهَا ‏ ‏يُرْوَى ذَلِكَ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ أَدْرَكَ مِنْ الْفَجْرِ رَكْعَةً قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَهَا ‏","","",""],[7467,7467,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَامَ أَعْرَابِيٌّ فَبَالَ فِي الْمَسْجِدِ فَتَنَاوَلَهُ النَّاسُ فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعُوهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَلَى بَوْلِهِ سَجْلَ مَاءٍ ‏ ‏أَوْ ‏ ‏ذَنُوبًا ‏ ‏مِنْ مَاءٍ ‏ ‏فَإِنَّمَا بُعِثْتُمْ مُيَسِّرِينَ وَلَمْ تُبْعَثُوا مُعَسِّرِينَ ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ أَعْرَابِيًّا بَالَ فِي الْمَسْجِدِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[7468,7468,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ خُطْوَةٍ ‏ ‏يَخْطُوهَا إِلَى الصَّلَاةِ يُكْتَبُ لَهُ بِهَا حَسَنَةٌ ‏ ‏وَيُمْحَى عَنْهُ بِهَا سَيِّئَةٌ ‏","","",""],[7469,7469,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الصَّلَاةِ وَقُمْنَا مَعَهُ فَقَالَ أَعْرَابِيٌّ وَهُوَ فِي الصَّلَاةِ اللَّهُمَّ ارْحَمْنِي ‏ ‏وَمُحَمَّدًا ‏ ‏وَلَا تَرْحَمْ مَعَنَا أَحَدًا فَلَمَّا سَلَّمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِلْأَعْرَابِيِّ ‏ ‏لَقَدْ ‏ ‏تَحَجَّرْتَ ‏ ‏وَاسِعًا يُرِيدُ رَحْمَةَ اللَّهِ ‏","","",""],[7470,7470,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ ‏ ‏الشَّيْطَانَ يَأْتِي أَحَدَكُمْ فِي صَلَاتِهِ فَلَا يَدْرِي أَنْ زَادَ أَمْ نَقَصَ فَإِذَا وَجَدَ أَحَدُكُمْ ذَلِكَ فَلْيَسْجُدْ سَجْدَتَيْنِ ‏","","",""],[7471,7471,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏رَبَاحٍ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أُقِيمَتْ الصَّلَاةُ وَصَفَّ النَّاسُ صُفُوفَهُمْ لِلصَّلَاةِ وَخَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ بَيْتِهِ فَأَقْبَلَ يَمْشِي حَتَّى ‏ ‏قَامَ فِي مُصَلَّاهُ ثُمَّ ذَكَرَ أَنَّهُ لَمْ يَغْتَسِلْ فَقَالَ لِلنَّاسِ مَكَانَكُمْ فَرَجَعَ إِلَى بَيْتِهِ قَالَ فَخَرَجَ عَلَيْنَا وَنَحْنُ صُفُوفٌ فَقَامَ فِي الصَّلَاةِ ‏ ‏يَنْطُفُ ‏ ‏رَأْسَهُ قَدْ اغْتَسَلَ ‏","","",""],[7472,7472,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمُحَمَّدُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَتَى أَحَدَكُمْ خَادِمُهُ ‏ ‏بِطَعَامِهِ ‏ ‏فَقَدْ ‏ ‏وَلِيَ ‏ ‏حَرَّهُ ‏ ‏وَمَشَقَّتَهُ ‏ ‏وَدُخَانَهُ ‏ ‏وَمُؤْنَتَهُ ‏ ‏فَلْيُجْلِسْهُ مَعَهُ فَإِنْ أَبَى فَلْيُنَاوِلْهُ أُكْلَةً فِي يَدِهِ ‏","","",""],[7473,7473,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سَعِيدًا الْمَقْبُرِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطَّاعِمُ الشَّاكِرُ كَالصَّائِمِ الصَّابِرِ ‏","","",""],[7474,7474,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏دَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْبَرَكَةِ فِي السَّحُورِ ‏ ‏وَالثَّرِيدِ ‏","","",""],[7475,7475,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ يَعْلَمُ الَّذِي يَشْرَبُ وَهُوَ قَائِمٌ مَا فِي بَطْنِهِ ‏ ‏لَاسْتَقَاءَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَمِثْلِ حَدِيثِ ‏ ‏الزُّهْرِيِّ ‏","","",""],[7476,7476,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ مِنْ مَجْلِسِهِ ثُمَّ رَجَعَ إِلَيْهِ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[7477,7477,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ أَحَدُكُمْ مِنْ اللَّيْلِ ثُمَّ رَجَعَ إِلَى فِرَاشِهِ فَلْيَنْفُضْ فِرَاشَهُ بِدَاخِلَةِ ‏ ‏إِزَارِهِ ‏ ‏فَإِنَّهُ لَا يَدْرِي مَا خَلَفَهُ بَعْدُ ثُمَّ لِيَقُلْ بِاسْمِكَ اللَّهُمَّ وَضَعْتُ جَنْبِي وَبِاسْمِكَ أَرْفَعُهُ اللَّهُمَّ إِنْ أَمْسَكْتَ نَفْسِي فَاغْفِرْ لَهَا وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ الصَّالِحِينَ ‏","","",""],[7478,7478,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا انْتَعَلَ أَحَدُكُمْ فَلْيَبْدَأْ بِالْيُمْنَى وَإِذَا خَلَعَ فَلْيَبْدَأْ بِالْيُسْرَى وَلْيَخْلَعْهُمَا جَمِيعًا وَلْيَنْعَلْهُمَا جَمِيعًا ‏","","",""],[7479,7479,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمْسٌ مِنْ الْفِطْرَةِ ‏ ‏الِاسْتِحْدَادُ ‏ ‏وَالْخِتَانُ ‏ ‏وَقَصُّ الشَّارِبِ وَنَتْفُ الْإِبْطِ وَتَقْلِيمُ الْأَظْفَارِ ‏","","",""],[7480,7480,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُؤْمِنِ كَمَثَلِ الزَّرْعِ لَا يَزَالُ الرِّيحُ ‏ ‏تُفِيئُهُ ‏ ‏وَلَا يَزَالُ الْمُؤْمِنُ يُصِيبُهُ بَلَاءٌ وَمَثَلُ الْمُنَافِقِ كَمَثَلِ شَجَرَةِ ‏ ‏الْأَرْزَةِ ‏ ‏لَا تَهْتَزُّ حَتَّى ‏ ‏تُسْتَحْصَدَ ‏","","",""],[7481,7481,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَيْقَظَ أَحَدُكُمْ فَلَا يُدْخِلْ يَدَهُ فِي إِنَائِهِ ‏ ‏أَوْ قَالَ فِي وَضُوئِهِ ‏ ‏حَتَّى يَغْسِلَهَا ثَلَاثَ مَرَّاتٍ فَإِنَّهُ لَا يَدْرِي أَيْنَ بَاتَتْ يَدُهُ ‏","","",""],[7482,7482,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏مَرَّ بِقَوْمٍ يَتَوَضَّئُونَ مِنْ ‏ ‏مَطْهَرَةٍ ‏ ‏فَقَالَ أَحْسِنُوا الْوُضُوءَ يَرْحَمْكُمْ اللَّهُ أَلَمْ تَسْمَعُوا مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏","","",""],[7483,7483,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏أُرَاهُ قَالَ عَنْ ‏ ‏ضَمْضَمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَقْتُلَ الْأَسْوَدَيْنِ فِي الصَّلَاةِ الْعَقْرَبَ وَالْحَيَّةَ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏هَكَذَا حَدَّثَنَا مَا لَا أُحْصِي ‏","","",""],[7484,7484,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَالثَّوْرِيُّ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنِ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ أَمِينٌ اللَّهُمَّ أَرْشِدْ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ ‏","","",""],[7485,7485,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أُكَيْمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى صَلَاةً جَهَرَ فِيهَا بِالْقِرَاءَةِ ثُمَّ أَقْبَلَ عَلَى النَّاسِ بَعْدَمَا سَلَّمَ فَقَالَ هَلْ قَرَأَ مِنْكُمْ أَحَدٌ مَعِي ‏ ‏آنِفًا ‏ ‏قَالُوا نَعَمْ يَا رَسُولَ اللَّهِ قَالَ إِنِّي أَقُولُ مَا لِي أُنَازَعُ الْقُرْآنَ فَانْتَهَى النَّاسُ عَنْ الْقِرَاءَةِ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَجْهَرُ بِهِ مِنْ الْقِرَاءَةِ حِينَ سَمِعُوا ذَلِكَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[7486,7486,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الظُّهْرَ ‏ ‏أَوْ الْعَصْرَ ‏ ‏فَسَلَّمَ فِي الرَّكْعَتَيْنِ ثُمَّ انْصَرَفَ فَخَرَجَ سَرَعَانُ النَّاسِ فَقَالُوا خُفِّفَتْ الصَّلَاةُ فَقَالَ ‏ ‏ذُو الشِّمَالَيْنِ ‏ ‏أَخُفِّفَتْ الصَّلَاةُ أَمْ نَسِيتَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَقُولُ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏قَالُوا صَدَقَ ‏ ‏فَصَلَّى بِهِمْ الرَّكْعَتَيْنِ اللَّتَيْنِ تَرَكَ ثُمَّ سَجَدَ سَجْدَتَيْنِ وَهُوَ جَالِسٌ بَعْدَ مَا سَلَّمَ ‏","","",""],[7487,7487,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَجْعَلُوا بُيُوتَكُمْ مَقَابِرَ فَإِنَّ الشَّيْطَانَ يَفِرُّ مِنْ الْبَيْتِ الَّذِي يُقْرَأُ فِيهِ سُورَةُ ‏ ‏الْبَقَرَةِ ‏","","",""],[7488,7488,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَعَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي أَحَدَكُمْ الشَّيْطَانُ فَيَلْبِسُ عَلَيْهِ فِي صَلَاتِهِ فَلَا يَدْرِي أَزَادَ أَمْ نَقَصَ فَإِذَا وَجَدَ أَحَدُكُمْ ذَلِكَ فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ ‏","","",""],[7489,7489,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ فِي الْجُمُعَةِ سَاعَةً لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ يَسْأَلُ اللَّهَ فِيهَا شَيْئًا إِلَّا أَعْطَاهُ إِيَّاهُ ‏","","",""],[7490,7490,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ فِي الْجُمُعَةِ سَاعَةً لَا يُوَافِقُهَا عَبْدٌ مُسْلِمٌ يَسْأَلُ اللَّهَ فِيهَا شَيْئًا إِلَّا أَعْطَاهُ إِيَّاهُ ‏","","",""],[7491,7491,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏تَلَقِّي الْأَجْلَابِ ‏ ‏فَمَنْ تَلَقَّى وَاشْتَرَى فَصَاحِبُهُ بِالْخِيَارِ إِذَا هَبَطَ السُّوقَ ‏","","",""],[7492,7492,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[7493,7493,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ الْبُرْسَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ يَعْنِي ابْنَ بُرْقَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَزِيدَ بْنَ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ ‏","","",""],[7494,7494,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَجْمَاءُ ‏ ‏جَرْحُهَا ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏","","",""],[7495,7495,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اشْتَدَّ الْحَرُّ ‏ ‏فَأَبْرِدُوا ‏ ‏بِالصَّلَاةِ فَإِنَّ شِدَّةَ الْحَرِّ مِنْ ‏ ‏فَيْحِ ‏ ‏جَهَنَّمَ ‏","","",""],[7496,7496,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏حَدِيثِ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدَّثَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ ‏ ‏أَيُصَلِّي الرَّجُلُ فِي الثَّوْبِ الْوَاحِدِ فَقَالَ أَلِكُلِّكُمْ ثَوْبَانِ ‏","","",""],[7497,7497,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ الْمُسَيَّبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَمْ يَرْفَعْهُ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[7498,7498,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَأْذَنْ اللَّهُ لِشَيْءٍ مَا أَذِنَ لِمَنْ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏لِمَنْ ‏ ‏يَتَغَنَّى ‏ ‏بِالْقُرْآنِ قَالَ صَاحِبٌ لَهُ زَادَ فِيمَا يَجْهَرُ بِهِ ‏","","",""],[7499,7499,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أُكَيْمَةَ ‏ ‏يَقُولُ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةً يَجْهَرُ فِيهَا ثُمَّ سَلَّمَ فَأَقْبَلَ عَلَى النَّاسِ فَقَالَ هَلْ قَرَأَ مَعِي أَحَدٌ ‏ ‏آنِفًا ‏ ‏قَالُوا نَعَمْ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِنِّي أَقُولُ مَا لِي أُنَازَعُ الْقُرْآنَ ‏","","",""],[7500,7500,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَطَاءٌ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَهُوَ يُخْبِرُهُمْ قَالَ ‏ ‏وَفِي كُلِّ صَلَاةٍ قُرْآنٌ فَمَا أَسْمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْمَعْنَاكُمْ وَمَا أَخْفَى مِنَّا أَخْفَيْنَاهُ مِنْكُمْ ‏","","",""],[7501,7501,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ الْفَزَارِيُّ ‏ ‏قَالَ ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لُعِنَ الَّذِينَ اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[7502,7502,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏أَنَّ ‏ ‏أَبَا السَّائِبِ ‏ ‏مَوْلَى ‏ ‏هِشَامِ بْنِ زُهْرَةَ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى صَلَاةً لَمْ يَقْرَأْ فِيهَا ‏ ‏بِأُمِّ الْقُرْآنِ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏هِيَ ‏ ‏خِدَاجٌ ‏ ‏غَيْرُ تَمَامٍ قَالَ ‏ ‏أَبُو السَّائِبِ ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏إِنِّي أَكُونُ أَحْيَانًا وَرَاءَ الْإِمَامِ قَالَ ‏ ‏أَبُو السَّائِبِ ‏ ‏فَغَمَزَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏ذِرَاعِي فَقَالَ يَا فَارِسِيُّ اقْرَأْهَا فِي نَفْسِكَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏قَسَمْتُ الصَّلَاةَ بَيْنِي وَبَيْنَ عَبْدِي نِصْفَيْنِ فَنِصْفُهَا لِي وَنِصْفُهَا لِعَبْدِي وَلِعَبْدِي مَا سَأَلَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَءُوا يَقُولُ فَيَقُولُ الْعَبْدُ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏فَيَقُولُ اللَّهُ حَمِدَنِي عَبْدِي وَيَقُولُ الْعَبْدُ ‏ { ‏الرَّحْمَنِ الرَّحِيمِ ‏} ‏فَيَقُولُ اللَّهُ أَثْنَى عَلَيَّ عَبْدِي فَيَقُولُ الْعَبْدُ ‏ { ‏مَالِكِ يَوْمِ الدِّينِ ‏} ‏فَيَقُولُ اللَّهُ مَجَّدَنِي عَبْدِي وَقَالَ هَذِهِ بَيْنِي وَبَيْنَ عَبْدِي يَقُولُ الْعَبْدُ ‏ { ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‏} ‏قَالَ أَجِدُهَا لِعَبْدِي وَلِعَبْدِي مَا سَأَلَ قَالَ يَقُولُ عَبْدِي ‏ { ‏اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ‏} ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ هَذَا لِعَبْدِي وَلِعَبْدِي مَا سَأَلَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏وَمُحَمَّدُ بْنُ عَبْدِ اللَّهِ الْأَنْصَارِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَا ‏ ‏كُلٌّ ‏ ‏مِنْهُمَا مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ هِشَامِ بْنِ زُهْرَةَ ‏ ‏وَقَالَا ‏ { ‏مَالِكِ ‏} ‏وَقَالَ ‏ ‏ابْنُ بَكْرٍ ‏ ‏يَقُولُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْرَءُوا يَقُومُ الْعَبْدُ فَيَقُولُ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَاه ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏الْعَلَاءُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ يَعْقُوبَ ‏ ‏مَوْلَى ‏ ‏الْحُرَقَةِ ‏ ‏عَنْ ‏ ‏أَبِي السَّائِبِ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ زُهْرَةَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[7503,7503,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَعْدَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو الْقَارِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏وَرَبِّ هَذَا ‏ ‏الْبَيْتِ ‏ ‏مَا أَنَا نَهَيْتُ عَنْ صِيَامِ يَوْمِ الْجُمُعَةِ وَلَكِنْ ‏ ‏مُحَمَّدٌ ‏ ‏نَهَى عَنْهُ وَرَبِّ هَذَا ‏ ‏الْبَيْتِ ‏ ‏مَا أَنَا قُلْتُ مَنْ أَدْرَكَهُ الصُّبْحُ جُنُبًا فَلْيُفْطِرْ وَلَكِنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏فِي حَدِيثِهِ ‏ ‏إِنَّ ‏ ‏يَحْيَى بْنَ جَعْدَةَ ‏ ‏أَخْبَرَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو الْقَارِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏","","",""],[7504,7504,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ يَوْمُ صَوْمِ أَحَدِكُمْ فَلَا ‏ ‏يَرْفُثْ ‏ ‏وَلَا يَجْهَلْ فَإِنْ جَهِلَ عَلَيْهِ أَحَدٌ فَلْيَقُلْ إِنِّي امْرُؤٌ صَائِمٌ ‏","","",""],[7505,7505,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا رَفَعَ غُصْنَ شَوْكٍ مِنْ طَرِيقِ الْمُسْلِمِينَ فَغُفِرَ لَهُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَهَذَا الْحَدِيثُ مَرْفُوعٌ وَلَكِنْ ‏ ‏سُفْيَانُ ‏ ‏قَصَّرَ فِي رَفْعِهِ ‏","","",""],[7506,7506,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏رَجُلٌ خَطَبَ امْرَأَةً فَقَالَ ‏ ‏يَعْنِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏انْظُرْ إِلَيْهَا فَإِنَّ فِي أَعْيُنِ ‏ ‏الْأَنْصَارِ ‏ ‏شَيْئًا ‏","","",""],[7507,7507,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ أَبُو أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الشِّغَارِ ‏","","",""],[7508,7508,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ اللَّهُ عَلَى لِسَانِي مَا بَيْنَ ‏ ‏لَابَتَيْ ‏ ‏الْمَدِينَةِ ‏ ‏ثُمَّ جَاءَ ‏ ‏بَنِي حَارِثَةَ ‏ ‏فَقَالَ يَا ‏ ‏بَنِي حَارِثَةَ ‏ ‏مَا أُرَاكُمْ إِلَّا قَدْ خَرَجْتُمْ مِنْ ‏ ‏الْحَرَمِ ‏ ‏ثُمَّ نَظَرَ فَقَالَ بَلْ أَنْتُمْ فِيهِ بَلْ أَنْتُمْ فِيهِ ‏","","",""],[7509,7509,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ فِي الطَّرِيقِ شِعْرًا ‏ ‏يَا لَيْلَةً مِنْ طُولِهَا وَعَنَائِهَا ‏ ‏عَلَى أَنَّهَا مِنْ دَارَةِ الْكُفْرِ ‏ ‏نَجَّتِ ‏ ‏قَالَ ‏ ‏وَأَبَقَ ‏ ‏مِنِّي غُلَامٌ لِي فِي الطَّرِيقِ قَالَ فَلَمَّا قَدِمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَايَعْتُهُ فَبَيْنَا أَنَا عِنْدَهُ إِذْ طَلَعَ الْغُلَامُ فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏هَذَا غُلَامُكَ قُلْتُ هُوَ لِوَجْهِ اللَّهِ فَأَعْتَقْتُهُ ‏","","",""],[7510,7510,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْإِيمَانَ ‏ ‏لَيَأْرِزُ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏كَمَا ‏ ‏تَأْرِزُ ‏ ‏الْحَيَّةُ إِلَى جُحْرِهَا ‏","","",""],[7511,7511,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ امْرَأَةً عُذِّبَتْ فِي هِرَّةٍ أَمْسَكَتْهَا حَتَّى مَاتَتْ مِنْ الْجُوعِ لَمْ تَكُنْ تُطْعِمُهَا وَلَمْ تُرْسِلْهَا فَتَأْكُلَ مِنْ حَشَرَاتِ الْأَرْضِ وَغُفِرَ لِرَجُلٍ نَحَّى غُصْنَ شَوْكٍ عَنْ الطَّرِيقِ ‏","","",""],[7512,7512,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو اللَّيْثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِرَاءٌ ‏ ‏فِي الْقُرْآنِ كُفْرٌ ‏","","",""],[7513,7513,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَبِي خَالِدٍ يَعْنِي إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏أَبِي مَالِكٍ الْأَسْلَمِيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَدَّ ‏ ‏مَاعِزَ بْنَ مَالِكٍ ‏ ‏ثَلَاثَ مِرَارٍ فَلَمَّا جَاءَ فِي الرَّابِعَةِ أَمَرَ بِهِ فَرُجِمَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏مِثْلَهُ ‏","","",""],[7514,7514,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُحَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ كَسْبِ الْإِمَاءِ ‏","","",""],[7515,7515,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَى أَحَدُكُمْ الْمَجْلِسَ فَلْيُسَلِّمْ فَإِنْ بَدَا لَهُ أَنْ يَقْعُدَ فَلْيُسَلِّمْ إِذَا قَامَ فَلَيْسَتْ الْأُولَى بِأَوْجَبَ مِنْ الْآخِرَةِ ‏","","",""],[7516,7516,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏و قَالَ ‏ ‏يَعْنِي ‏ ‏عَبْدَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[7517,7517,"","","‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ النَّجَّارِ أَبُو إِسْمَاعِيلَ الْيَمَامِيُّ ‏ ‏عَنْ ‏ ‏طَيِّبِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُخَنَّثِي ‏ ‏الرِّجَالِ الَّذِينَ يَتَشَبَّهُونَ بِالنِّسَاءِ ‏ ‏وَالْمُتَرَجِّلَاتِ ‏ ‏مِنْ النِّسَاءِ الْمُتَشَبِّهِينَ بِالرِّجَالِ وَرَاكِبَ ‏ ‏الْفَلَاةِ ‏ ‏وَحْدَهُ ‏","","",""],[7518,7518,"","","‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ النَّجَّارِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏ ‏فَقَالَ يَا ‏ ‏آدَمُ ‏ ‏أَنْتَ الَّذِي أَخْرَجْتَ النَّاسَ مِنْ الْجَنَّةِ بِذَنْبِكَ وَأَشْقَيْتَهُمْ قَالَ فَقَالَ لَهُ ‏ ‏آدَمُ ‏ ‏أَنْتَ الَّذِي ‏ ‏اصْطَفَاكَ ‏ ‏اللَّهُ عَلَى النَّاسِ بِرِسَالَاتِهِ وَكَلَامِهِ فَتَلُومُنِي عَلَى أَمْرٍ كَتَبَهُ اللَّهُ أَوْ قَدَّرَهُ عَلَيَّ قَبْلَ أَنْ يَخْلُقَنِي قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَجَّ ‏ ‏آدَمُ ‏ ‏مُوسَى ‏","","",""],[7519,7519,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ ‏ ‏أَوْ ‏ ‏ابْنِ يَعْقُوبَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِزْرَةُ ‏ ‏الْمُؤْمِنِ إِلَى عَضَلَةِ سَاقَيْهِ ثُمَّ إِلَى نِصْفِ سَاقَيْهِ ثُمَّ إِلَى كَعْبَيْهِ فَمَا كَانَ أَسْفَلَ مِنْ ذَلِكَ فِي النَّارِ ‏","","",""],[7520,7520,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ الْجُعْفِيُّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِيَّاكُمْ وَالظَّنَّ فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ لَا ‏ ‏تَجَسَّسُوا ‏ ‏وَلَا ‏ ‏تَحَسَّسُوا ‏ ‏وَلَا تَنَافَسُوا وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا ‏ ‏تَبَاغَضُوا ‏ ‏وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[7521,7521,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ الْبَلَاءُ بِالْمُؤْمِنِ أَوْ الْمُؤْمِنَةِ فِي جَسَدِهِ وَفِي مَالِهِ وَفِي وَلَدِهِ حَتَّى يَلْقَى اللَّهَ وَمَا عَلَيْهِ مِنْ خَطِيئَةٍ ‏","","",""],[7522,7522,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مُرَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجِنَازَةٍ فَقَالَ ‏ ‏قُومُوا فَإِنَّ لِلْمَوْتِ ‏ ‏فَزَعًا ‏","","",""],[7523,7523,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَرَكَ مَالًا فَلِأَهْلِهِ وَمَنْ تَرَكَ ضَيَاعًا فَإِلَيَّ ‏","","",""],[7524,7524,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجُلٍ مُضْطَجِعٍ عَلَى بَطْنِهِ فَقَالَ ‏ ‏إِنَّ هَذِهِ لَضِجْعَةٌ مَا يُحِبُّهَا اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[7525,7525,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْأَعْمَالِ أَفْضَلُ وَأَيُّ الْأَعْمَالِ خَيْرٌ قَالَ إِيمَانٌ بِاللَّهِ وَرَسُولِهِ قَالَ ثُمَّ أَيٌّ يَا رَسُولَ اللَّهِ قَالَ الْجِهَادُ فِي سَبِيلِ اللَّهِ ‏ ‏سَنَامُ ‏ ‏الْعَمَلِ قَالَ ثُمَّ أَيٌّ يَا رَسُولَ اللَّهِ قَالَ حَجٌّ ‏ ‏مَبْرُورٌ ‏","","",""],[7526,7526,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْهِلَالَ قَالَ ‏ ‏إِذَا رَأَيْتُمُوهُ فَصُومُوا وَإِذَا رَأَيْتُمُوهُ فَأَفْطِرُوا فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَعُدُّوا ثَلَاثِينَ ‏","","",""],[7527,7527,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ أَبِي صَالِحٍ السَّمَّانُ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَصْبِرُ أَحَدٌ عَلَى ‏ ‏لَأْوَاءِ ‏ ‏الْمَدِينَةِ ‏ ‏وَجَهْدِهَا إِلَّا كُنْتُ لَهُ شَفِيعًا وَشَهِيدًا ‏ ‏أَوْ شَهِيدًا وَشَفِيعًا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏شَكَّ فِيهِ شَهِيدًا أَوْ شَفِيعًا ‏","","",""],[7528,7528,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏حُسَيْنُ بْنُ وَاقِدٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏","","",""],[7529,7529,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏قَالَ قَالَ سَمِعْتُ ‏ ‏أَبَا مَرْيَمَ ‏ ‏يَذْكُرُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُبَالَ فِي الْمَاءِ ‏ ‏الرَّاكِدِ ‏ ‏ثُمَّ يُتَوَضَّأَ مِنْهُ ‏","","",""],[7530,7530,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ هِلَالٍ الْقُرَشِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ فَلَمَّا قَامَ قُمْنَا مَعَهُ فَجَاءَهُ أَعْرَابِيٌّ فَقَالَ أَعْطِنِي يَا ‏ ‏مُحَمَّدُ ‏ ‏قَالَ فَقَالَ ‏ ‏لَا وَأَسْتَغْفِرُ اللَّهَ فَجَذَبَهُ ‏ ‏فَخَدَشَهُ ‏ ‏قَالَ فَهَمُّوا بِهِ قَالَ دَعُوهُ قَالَ ثُمَّ أَعْطَاهُ قَالَ وَكَانَتْ يَمِينُهُ أَنْ يَقُولَ لَا وَأَسْتَغْفِرُ اللَّهَ ‏","","",""],[7531,7531,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ ثَوْبَانَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ الْفَضْلِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَعَوَّذُ مِنْ أَرْبَعٍ مِنْ عَذَابِ جَهَنَّمَ وَعَذَابِ الْقَبْرِ وَفِتْنَةِ الْمَحْيَا وَالْمَمَاتِ وَفِتْنَةِ ‏ ‏الدَّجَّالِ ‏","","",""],[7532,7532,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ ظَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ ‏ ‏حَدَّثَ ‏ ‏مَرْوَانَ بْنَ الْحَكَمِ ‏ ‏قَالَ حَدَّثَنِي حِبِّي ‏ ‏أَبُو الْقَاسِمِ ‏ ‏الصَّادِقُ الْمَصْدُوقُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَلَاكَ أُمَّتِي عَلَى يَدَيْ غِلْمَةٍ ‏ ‏سُفَهَاءَ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏","","",""],[7533,7533,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَنْظَلَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏سَمِعْتُ ‏ ‏سَالِمَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏مَا أَدْرِي كَمْ رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَائِمًا فِي السُّوقِ يَقُولُ ‏ ‏يُقْبَضُ الْعِلْمُ وَتَظْهَرُ الْفِتَنُ وَيَكْثُرُ ‏ ‏الْهَرْجُ ‏ ‏قَالَ قِيلَ يَا رَسُولَ اللَّهِ وَمَا ‏ ‏الْهَرْجُ ‏ ‏قَالَ بِيَدِهِ هَكَذَا وَحَرَّفَهَا ‏","","",""],[7534,7534,"","","‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ فَمَا كَانَ بَعْدَ ذَلِكَ فَهُوَ ‏ ‏صَدَقَةٌ ‏","","",""],[7535,7535,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَنْ يَمْتَلِئَ جَوْفُ الرَّجُلِ ‏ ‏قَيْحًا ‏ ‏يَرِيهِ خَيْرٌ لَهُ مِنْ أَنْ يَمْتَلِئَ شِعْرًا ‏","","",""],[7536,7536,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ نَبْهَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَبَاغَضُوا ‏ ‏وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا ‏ ‏تَحَاسَدُوا ‏ ‏وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[7537,7537,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الْجَحَّافِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّهُمَا فَقَدْ أَحَبَّنِي وَمَنْ أَبْغَضَهُمَا فَقَدْ أَبْغَضَنِي ‏ ‏يَعْنِي ‏ ‏حَسَنًا ‏ ‏وَحُسَيْنًا ‏","","",""],[7538,7538,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏عَنْ ‏ ‏ابْنِ ثَوْبَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْفَضْلِ الْهَاشِمِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ تَوَضَّأَ مَرَّتَيْنِ ‏","","",""],[7539,7539,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَاللَّهِ لَا يُؤْمِنُ وَاللَّهِ لَا يُؤْمِنُ وَاللَّهِ لَا يُؤْمِنُ قَالُوا وَمَا ذَاكَ يَا رَسُولَ اللَّهِ قَالَ الْجَارُ لَا يَأْمَنُ جَارُهُ ‏ ‏بَوَائِقَهُ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ وَمَا بَوَائِقُهُ قَالَ شَرُّهُ ‏","","",""],[7540,7540,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عَجْلَانَ ‏ ‏مَوْلَى ‏ ‏الْمُشْمَعِلِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ مَوْلُودٍ مِنْ بَنِي ‏ ‏آدَمَ ‏ ‏يَمَسُّهُ الشَّيْطَانُ بِأُصْبُعِهِ إِلَّا ‏ ‏مَرْيَمَ ابْنَةَ عِمْرَانَ ‏ ‏وَابْنَهَا ‏ ‏عِيسَى ‏ ‏عَلَيْهِمَا السَّلَام ‏","","",""],[7541,7541,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ كَانَ مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَرَأَى ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَرَسًا مِنْ ‏ ‏رِقَاعٍ ‏ ‏فِي يَدِ جَارِيَةٍ فَقَالَ أَلَا ‏ ‏تَرَى هَذَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا يَعْمَلُ هَذَا مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ يَوْمَ الْقِيَامَةَ ‏","","",""],[7542,7542,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُرَغِّبُ النَّاسَ فِي قِيَامِ رَمَضَانَ وَيَقُولُ ‏ ‏مَنْ قَامَهُ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَلَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ النَّاسَ عَلَى الْقِيَامِ ‏","","",""],[7543,7543,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏فُقِدَ ‏ ‏سِبْطٌ ‏ ‏مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَذَكَرَ الْفَأْرَةَ فَقَالَ ‏ ‏أَلَا ‏ ‏تَرَى أَنَّكَ لَوْ أَدْنَيْتَ مِنْهَا لَبَنَ الْإِبِلِ لَمْ تَقْرَبْهُ وَإِنْ قَرَّبْتَ إِلَيْهَا لَبَنَ الْغَنَمِ شَرِبَتْهُ فَقَالَ أَكَذَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفَأَقْرَأُ التَّوْرَاةَ ‏","","",""],[7544,7544,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطِّيَرَةُ ‏ ‏فِي ثَلَاثٍ فِي الْمَسْكَنِ وَالْفَرَسِ وَالْمَرْأَةِ قَالَ قُلْتُ إِذَنْ أَقُولَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَمْ يَقُلْ وَلَكِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ أَصْدَقُ ‏ ‏الطِّيَرَةِ ‏ ‏الْفَأْلُ ‏ ‏وَالْعَيْنُ ‏ ‏حَقٌّ ‏","","",""],[7545,7545,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏أَخْبَرَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْغَادِيَةَ الْيَمَامِيَّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فَجَاءَ رَسُولُ ‏ ‏كَثِيرِ بْنِ الصَّلْتِ ‏ ‏فَدَعَاهُمْ فَمَا قَامَ إِلَّا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَخَمْسَةٌ مِنْهُمْ أَنَا أَحَدُهُمْ فَذَهَبُوا فَأَكَلُوا ثُمَّ جَاءَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَغَسَلَ يَدَهُ ثُمَّ قَالَ وَاللَّهِ يَا أَهْلَ الْمَسْجِدِ إِنَّكُمْ لَعُصَاةٌ ‏ ‏لِأَبِي الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[7546,7546,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى ‏ ‏النَّجَاشِيِّ ‏ ‏فَكَبَّرَ عَلَيْهِ أَرْبَعًا ‏","","",""],[7547,7547,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَيْحَانُ ‏ ‏وَجَيْحَانُ وَالنِّيلُ وَالْفُرَاتُ كُلٌّ مِنْ أَنْهَارِ الْجَنَّةِ ‏","","",""],[7548,7548,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ بْنُ إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏بُرْدُ بْنُ سِنَانٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ نَبِيٍّ وَلَا خَلِيفَةٍ ‏ ‏أَوْ قَالَ مَا مِنْ نَبِيٍّ ‏ ‏إِلَّا وَلَهُ ‏ ‏بِطَانَتَانِ ‏ ‏بِطَانَةٌ ‏ ‏تَأْمُرُهُ بِالْمَعْرُوفِ ‏ ‏وَتَنْهَاهُ عَنْ الْمُنْكَرِ ‏ ‏وَبِطَانَةٌ ‏ ‏لَا ‏ ‏تَأْلُوهُ ‏ ‏خَبَالًا ‏ ‏وَمَنْ وُقِيَ شَرَّ ‏ ‏بِطَانَةِ ‏ ‏السُّوءِ فَقَدْ وُقِيَ يَقُولُهَا ثَلَاثًا وَهُوَ مَعَ الْغَالِبَةِ عَلَيْهِ مِنْهُمَا ‏","","",""],[7549,7549,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُبَارَكٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏إِذَا اسْتَنْشَقَ أَدْخَلَ الْمَاءَ ‏ ‏فِي مَنْخِرَيْهِ ‏","","",""],[7550,7550,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ أَبِي قُرَّةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي حُرَّةَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏حَكِيمِ بْنِ أَبِي حُرَّةَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلطَّاعِمِ الشَّاكِرِ مِثْلُ مَا لِلصَّائِمِ الصَّابِرِ ‏","","",""],[7551,7551,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ بْنُ أَبِي قُرَّةَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ سَلْمَانَ الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا يَنْبَغِي لِذِي الْوَجْهَيْنِ أَنْ يَكُونَ أَمِينًا ‏","","",""],[7552,7552,"","","‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ النَّجَّارِ ‏ ‏عَنْ ‏ ‏طَيِّبِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُخَنَّثِي ‏ ‏الرِّجَالِ الَّذِينَ يَتَشَبَّهُونَ بِالنِّسَاءِ وَالْمُتَرَجِّلَاتِ مِنْ النِّسَاءِ الْمُتَشَبِّهِينَ بِالرِّجَالِ ‏ ‏وَالْمُتَبَتِّلِينَ ‏ ‏مِنْ الرِّجَالِ الَّذِينَ يَقُولُونَ لَا نَتَزَوَّجُ ‏ ‏وَالْمُتَبَتِّلَاتِ ‏ ‏مِنْ النِّسَاءِ اللَّائِي يَقُلْنَ ذَلِكَ وَرَاكِبَ الْفَلَاةِ وَحْدَهُ فَاشْتَدَّ ذَلِكَ عَلَى ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى اسْتَبَانَ ذَلِكَ فِي وُجُوهِهِمْ وَقَالَ الْبَائِتُ وَحْدَهُ ‏","","",""],[7553,7553,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ بُوذَوَيْهِ ‏ ‏أَخْبَرَنِي ‏ ‏مَنْ سَمِعَ ‏ ‏وَهْبًا ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏يَعْنِي ‏ ‏هَمَّامًا ‏ ‏كَذَا قَالَ أَبِي ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ أَحَدُكُمْ فِي صَلَاةٍ مَا دَامَ يَنْتَظِرُ ‏ ‏الَّتِي بَعْدَهَا وَلَا تَزَالُ الْمَلَائِكَةُ تُصَلِّي عَلَى أَحَدِكُمْ مَا دَامَ فِي مَسْجِدِهِ تَقُولُ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ مَا لَمْ يُحْدِثْ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏رَجُلٌ مِنْ أَهْلِ ‏ ‏حَضْرَمَوْتَ ‏ ‏وَمَا ذَلِكَ الْحَدَثُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ لَا يَسْتَحْيِي مِنْ الْحَقِّ إِنْ فَسَا أَوْ ضَرَطَ ‏","","",""],[7554,7554,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ الْفَزَارِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ كَيْسَانَ ‏ ‏اسْتَأْذَنَ عَلَى ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَسَبَّحَ لِي فَلَمَّا سَلَّمَ قَالَ ‏ ‏إِنَّ إِذْنَ الرَّجُلِ إِذَا كَانَ فِي الصَّلَاةِ أَنْ يُسَبِّحَ وَإِنَّ إِذْنَ الْمَرْأَةِ أَنْ تُصَفِّقَ ‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ ‏ ‏أَخْبَرَنَا ‏ ‏عَوْفٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ ‏ ‏أَخْبَرَنِي ‏ ‏عَوْفٌ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[7555,7555,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏وِتْرٌ ‏ ‏يُحِبُّ ‏ ‏الْوِتْرَ ‏","","",""],[7556,7556,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نُهِيَ عَنْ ‏ ‏الِاخْتِصَارِ فِي الصَّلَاةِ ‏ ‏قَالَ قُلْنَا ‏ ‏لِهِشَامٍ ‏ ‏مَا ‏ ‏الِاخْتِصَارُ قَالَ يَضَعُ يَدَهُ عَلَى خَصْرِهِ وَهُوَ ‏ ‏يُصَلِّي ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏قُلْنَا ‏ ‏لِهِشَامٍ ‏ ‏ذَكَرَهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بِرَأْسِهِ أَيْ نَعَمْ ‏","","",""],[7557,7557,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ إِذَا أَمْسَى ثَلَاثَ مَرَّاتٍ أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ لَمْ تَضُرَّهُ حُمَةٌ تِلْكَ اللَّيْلَةَ ‏ ‏قَالَ ‏ ‏فَكَانَ أَهْلُنَا قَدْ تَعَلَّمُوهَا فَكَانُوا يَقُولُونَهَا فَلُدِغَتْ جَارِيَةٌ مِنْهُمْ فَلَمْ تَجِدْ لَهَا وَجَعًا ‏","","",""],[7558,7558,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا شَهِدَ جَنَازَةً سَأَلَ هَلْ عَلَى صَاحِبِكُمْ دَيْنٌ فَإِنْ قَالُوا نَعَمْ قَالَ هَلْ لَهُ وَفَاءٌ فَإِنْ قَالُوا نَعَمْ صَلَّى عَلَيْهِ وَإِنْ قَالُوا لَا قَالَ صَلُّوا عَلَى صَاحِبِكُمْ فَلَمَّا فَتَحَ اللَّهُ عَزَّ وَجَلَّ عَلَيْهِ الْفُتُوحَ قَالَ ‏ ‏أَنَا أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ فَمَنْ تَرَكَ دَيْنًا فَعَلَيَّ وَمَنْ تَرَكَ مَالًا فَلِوَرَثَتِهِ ‏","","",""],[7559,7559,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنِ ‏ ‏ابْنِ مِكْرَزٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ الرَّجُلُ يُرِيدُ الْجِهَادَ فِي سَبِيلِ اللَّهِ وَهُوَ يَبْتَغِي عَرَضَ الدُّنْيَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَجْرَ لَهُ فَأَعْظَمَ النَّاسُ ذَلِكَ وَقَالُوا لِلرَّجُلِ عُدْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَلَّهُ لَمْ يَفْهَمْ فَعَادَ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏الرَّجُلُ يُرِيدُ الْجِهَادَ فِي سَبِيلِ اللَّهِ وَهُوَ يَبْتَغِي عَرَضَ الدُّنْيَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَجْرَ لَهُ ثُمَّ عَادَ الثَّالِثَةَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَجْرَ لَهُ ‏","","",""],[7560,7560,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ الْمُغِيرَةِ بْنِ نَوْفَلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ صَلَاةٍ لَا يُقْرَأُ فِيهَا ‏ ‏بِأُمِّ الْقُرْآنِ ‏ ‏فَهِيَ ‏ ‏خِدَاجٌ ‏ ‏ثُمَّ هِيَ ‏ ‏خِدَاجٌ ‏","","",""],[7561,7561,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ حَكِيمٍ الضَّبِّيِّ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏إِذَا أَتَيْتَ أَهْلَ مِصْرِكَ فَأَخْبِرْهُمْ أَنِّي ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَوَّلُ شَيْءٍ مِمَّا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ صَلَاتُهُ الْمَكْتُوبَةُ فَإِنْ صَلَحَتْ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏مَرَّةً فَإِنْ أَتَمَّهَا ‏ ‏وَإِلَّا زِيدَ فِيهَا مِنْ تَطَوُّعِهِ ثُمَّ يُفْعَلُ بِسَائِرِ الْأَعْمَالِ الْمَفْرُوضَةِ كَذَلِكَ ‏","","",""],[7562,7562,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْزِلُ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏فَيَقْتُلُ الْخِنْزِيرَ ‏ ‏وَيَمْحُو الصَّلِيبَ وَتُجْمَعُ لَهُ الصَّلَاةُ وَيُعْطَى الْمَالُ حَتَّى لَا يُقْبَلَ وَيَضَعُ الْخَرَاجَ وَيَنْزِلُ ‏ ‏الرَّوْحَاءَ ‏ ‏فَيَحُجُّ مِنْهَا أَوْ يَعْتَمِرُ أَوْ يَجْمَعُهُمَا ‏ ‏قَالَ ‏ ‏وَتَلَا ‏ ‏أَبُو هُرَيْرَةَ ‏ { ‏وَإِنْ مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏إِلَّا لَيُؤْمِنَنَّ بِهِ قَبْلَ مَوْتِهِ وَيَوْمَ الْقِيَامَةِ يَكُونُ عَلَيْهِمْ شَهِيدًا ‏} ‏فَزَعَمَ ‏ ‏حَنْظَلَةُ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ يُؤْمِنُ بِهِ قَبْلَ مَوْتِهِ ‏ ‏عِيسَى ‏ ‏فَلَا أَدْرِي هَذَا كُلُّهُ حَدِيثُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ شَيْءٌ قَالَهُ ‏ ‏أَبُو هُرَيْرَةَ ‏","","",""],[7563,7563,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ هُرْمُزَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُرَيْشٌ ‏ ‏وَالْأَنْصَارُ ‏ ‏وَجُهَيْنَةُ ‏ ‏وَمُزَيْنَةُ ‏ ‏وَأَسْلَمُ ‏ ‏وَغِفَارٌ ‏ ‏وَأَشْجَعُ ‏ ‏مَوَالِيَّ لَيْسَ لَهُمْ مَوْلًى دُونَ اللَّهِ وَرَسُولِهِ ‏","","",""],[7564,7564,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ كُلَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجْتُ إِلَيْكُمْ وَقَدْ بُيِّنَتْ لِي لَيْلَةُ الْقَدْرِ ‏ ‏ومَسِيحُ الضَّلَالَةِ ‏ ‏فَكَانَ تَلَاحٍ بَيْنَ رَجُلَيْنِ بِسُدَّةِ الْمَسْجِدِ فَأَتَيْتُهُمَا لِأَحْجِزَ بَيْنَهُمَا فَأُنْسِيتُهُمَا ‏ ‏وَسَأَشْدُو لَكُمْ مِنْهُمَا شَدْوًا أَمَّا لَيْلَةُ الْقَدْرِ فَالْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ ‏ ‏وِتْرًا ‏ ‏وَأَمَّا ‏ ‏مَسِيحُ الضَّلَالَةِ ‏ ‏فَإِنَّهُ أَعْوَرُ الْعَيْنِ أَجْلَى الْجَبْهَةِ عَرِيضُ النَّحْرِ فِيهِ ‏ ‏دَفَأٌ ‏ ‏كَأَنَّهُ ‏ ‏قَطَنُ بْنُ عَبْدِ الْعُزَّى ‏ ‏قَالَ يَا رَسُولَ اللَّهِ هَلْ يَضُرُّنِي شَبَهُهُ قَالَ لَا أَنْتَ امْرُؤٌ مُسْلِمٌ وَهُوَ امْرُؤٌ كَافِرٌ ‏","","",""],[7565,7565,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَوْنٍ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِجَارِيَةٍ ‏ ‏سَوْدَاءَ أَعْجَمِيَّةٍ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ عَلَيَّ عِتْقَ رَقَبَةٍ مُؤْمِنَةٍ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْنَ اللَّهُ فَأَشَارَتْ إِلَى السَّمَاءِ بِإِصْبَعِهَا السَّبَّابَةِ فَقَالَ لَهَا مَنْ أَنَا فَأَشَارَتْ بِإِصْبَعِهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِلَى السَّمَاءِ أَيْ أَنْتَ رَسُولُ اللَّهِ فَقَالَ أَعْتِقْهَا ‏","","",""],[7566,7566,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنِ ‏ ‏الْمَسْعُودِيِّ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَكْثَرِ مَا ‏ ‏يَلِجُ ‏ ‏النَّاسُ بِهِ النَّارَ فَقَالَ ‏ ‏الْأَجْوَفَانِ الْفَمُ وَالْفَرْجُ وَسُئِلَ عَنْ أَكْثَرِ مَا ‏ ‏يَلِجُ ‏ ‏بِهِ الْجَنَّةَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُسْنُ الْخُلُقِ ‏","","",""],[7567,7567,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏أَبِي الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعٌ مِنْ أَمْرِ الْجَاهِلِيَّةِ لَنْ يَدَعَهُنَّ النَّاسُ التَّعْيِيرُ فِي الْأَحْسَابِ ‏ ‏وَالنِّيَاحَةُ ‏ ‏عَلَى الْمَيِّتِ ‏ ‏وَالْأَنْوَاءُ ‏ ‏وَأَجْرَبَ بَعِيرٌ فَأَجْرَبَ مِائَةً مَنْ أَجْرَبَ الْبَعِيرَ الْأَوَّلَ ‏","","",""],[7568,7568,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُولُوا لِحَائِطِ الْعِنَبِ الْكَرْمَ فَإِنَّمَا الْكَرْمُ الرَّجُلُ الْمُؤْمِنُ ‏","","",""],[7569,7569,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سَمْعَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُخْبِرُ ‏ ‏أَبَا قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُبَايَعُ لِرَجُلٍ مَا بَيْنَ الرُّكْنِ ‏ ‏وَالْمَقَامِ ‏ ‏وَلَنْ يَسْتَحِلَّ ‏ ‏الْبَيْتَ ‏ ‏إِلَّا أَهْلُهُ فَإِذَا اسْتَحَلُّوهُ فَلَا يُسْأَلُ عَنْ هَلَكَةِ ‏ ‏الْعَرَبِ ‏ ‏ثُمَّ تَأْتِي ‏ ‏الْحَبَشَةُ ‏ ‏فَيُخَرِّبُونَهُ خَرَابًا لَا يَعْمُرُ بَعْدَهُ أَبَدًا وَهُمْ الَّذِينَ يَسْتَخْرِجُونَ كَنْزَهُ ‏","","",""],[7570,7570,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ سَكِرَ فَاجْلِدُوهُ ثُمَّ إِنْ سَكِرَ فَاجْلِدُوهُ فَإِنْ عَادَ فِي الرَّابِعَةِ فَاضْرِبُوا عُنُقَهُ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجُلٍ سَكْرَانَ فِي الرَّابِعَةِ فَخَلَّى سَبِيلَهُ ‏","","",""],[7571,7571,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنْبَأَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ قُدَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ بَكْرِ بْنِ أَبِي الْفُرَاتِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا سَتَأْتِي عَلَى النَّاسِ ‏ ‏سِنُونَ خَدَّاعَةٌ يُصَدَّقُ فِيهَا الْكَاذِبُ وَيُكَذَّبُ فِيهَا الصَّادِقُ وَيُؤْتَمَنُ فِيهَا الْخَائِنُ وَيُخَوَّنُ فِيهَا الْأَمِينُ وَيَنْطِقُ فِيهَا الرُّوَيْبِضَةُ قِيلَ وَمَا الرُّوَيْبِضَةُ قَالَ السَّفِيهُ يَتَكَلَّمُ فِي أَمْرِ الْعَامَّةِ ‏","","",""],[7572,7572,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنْ ‏ ‏أَبِي الرَّبِيعِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَإِسْرَافِي وَمَا أَنْتَ أَعْلَمُ ‏ ‏بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ ‏","","",""],[7573,7573,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مِهْرَانَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏حِينَ حَضَرَهُ الْمَوْتُ لَا تَضْرِبُوا عَلَيَّ ‏ ‏فُسْطَاطًا ‏ ‏وَلَا تَتْبَعُونِي ‏ ‏بِمِجْمَرٍ ‏ ‏وَأَسْرِعُوا بِي فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا وُضِعَ الرَّجُلُ الصَّالِحُ عَلَى سَرِيرِهِ قَالَ قَدِّمُونِي قَدِّمُونِي وَإِذَا وُضِعَ الرَّجُلُ السُّوءُ عَلَى سَرِيرِهِ قَالَ يَا وَيْلَهُ أَيْنَ تَذْهَبُونَ بِي ‏","","",""],[7574,7574,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ مَوْلُودٍ يُولَدُ مِنْ بَنِي ‏ ‏آدَمَ ‏ ‏يَمَسُّهُ الشَّيْطَانُ بِإِصْبَعِهِ إِلَّا ‏ ‏مَرْيَمَ ‏ ‏وَابْنَهَا ‏ ‏عَلَيْهِمَا السَّلَام ‏","","",""],[7575,7575,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عَجْلَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَنْتَهِيَنَّ رِجَالٌ مِمَّنْ حَوْلَ الْمَسْجِدِ لَا يَشْهَدُونَ الْعِشَاءَ الْآخِرَةَ فِي الْجَمِيعِ أَوْ لَأُحَرِّقَنَّ حَوْلَ بُيُوتِهِمْ بِحُزَمِ الْحَطَبِ ‏","","",""],[7576,7576,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ أَبِي هِشَامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُعْطِيَتْ أُمَّتِي خَمْسَ خِصَالٍ فِي رَمَضَانَ لَمْ تُعْطَهَا أُمَّةٌ قَبْلَهُمْ ‏ ‏خُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ وَتَسْتَغْفِرُ لَهُمْ الْمَلَائِكَةُ حَتَّى يُفْطِرُوا وَيُزَيِّنُ اللَّهُ عَزَّ وَجَلَّ كُلَّ يَوْمٍ جَنَّتَهُ ثُمَّ يَقُولُ يُوشِكُ عِبَادِي الصَّالِحُونَ أَنْ يُلْقُوا عَنْهُمْ الْمَئُونَةَ وَالْأَذَى وَيَصِيرُوا إِلَيْكِ ‏ ‏وَيُصَفَّدُ ‏ ‏فِيهِ مَرَدَةُ الشَّيَاطِينِ فَلَا يَخْلُصُوا إِلَى مَا كَانُوا يَخْلُصُونَ إِلَيْهِ فِي غَيْرِهِ وَيُغْفَرُ لَهُمْ فِي آخِرِ لَيْلَةٍ قِيلَ يَا رَسُولَ اللَّهِ أَهِيَ لَيْلَةُ الْقَدْرِ قَالَ لَا وَلَكِنَّ الْعَامِلَ إِنَّمَا يُوَفَّى أَجْرَهُ إِذَا قَضَى عَمَلَهُ ‏","","",""],[7577,7577,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ أَعْرَابِيًّا أَهْدَى إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَكْرَةً ‏ ‏فَعَوَّضَهُ سِتَّ ‏ ‏بَكَرَاتٍ ‏ ‏فَتَسَخَّطَهُ ‏ ‏فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ ‏ ‏إِنَّ فُلَانًا أَهْدَى إِلَيَّ نَاقَةً وَهِيَ نَاقَتِي أَعْرِفُهَا كَمَا أَعْرِفُ بَعْضَ أَهْلِي ذَهَبَتْ مِنِّي يَوْمَ ‏ ‏زَغَابَاتٍ فَعَوَّضْتُهُ سِتَّ ‏ ‏بَكَرَاتٍ ‏ ‏فَظَلَّ ‏ ‏سَاخِطًا ‏ ‏لَقَدْ هَمَمْتُ أَنْ لَا أَقْبَلَ هَدِيَّةً إِلَّا مِنْ قُرَشِيٍّ أَوْ أَنْصَارِيٍّ أَوْ ثَقَفِيٍّ أَوْ ‏ ‏دَوْسِيٍّ ‏","","",""],[7578,7578,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَجُلٌ يَزُورُ أَخًا لَهُ فِي اللَّهِ عَزَّ وَجَلَّ فِي قَرْيَةٍ أُخْرَى ‏ ‏فَأَرْصَدَ ‏ ‏اللَّهُ عَزَّ وَجَلَّ ‏ ‏بِمَدْرَجَتِهِ ‏ ‏مَلَكًا فَلَمَّا مَرَّ بِهِ قَالَ أَيْنَ تُرِيدُ قَالَ أُرِيدُ فُلَانًا قَالَ لِقَرَابَةٍ قَالَ لَا قَالَ فَلِنِعْمَةٍ لَهُ عِنْدَكَ تَرُبُّهَا قَالَ لَا قَالَ فَلِمَ تَأْتِيهِ قَالَ إِنِّي أُحِبُّهُ فِي اللَّهِ قَالَ فَإِنِّي رَسُولُ اللَّهِ إِلَيْكَ أَنَّهُ يُحِبُّكَ بِحُبِّكَ إِيَّاهُ فِيهِ ‏","","",""],[7579,7579,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏فَرْقَدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَكْذَبُ النَّاسِ ‏ ‏أَوْ مِنْ أَكْذَبِ النَّاسِ ‏ ‏الصَّوَّاغُونَ وَالصَّبَّاغُونَ ‏","","",""],[7580,7580,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ آتَاهُ اللَّهُ مِنْ هَذَا الْمَالِ شَيْئًا مِنْ غَيْرِ أَنْ يَسْأَلَهُ فَلْيَقْبَلْهُ فَإِنَّمَا هُوَ رِزْقٌ سَاقَهُ اللَّهُ عَزَّ وَجَلَّ إِلَيْهِ ‏","","",""],[7581,7581,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏مَنْ أَغْلَقَ بَابَهُ فَهُوَ آمِنٌ وَمَنْ دَخَلَ دَارَ ‏ ‏أَبِي سُفْيَانَ ‏ ‏فَهُوَ آمِنٌ ‏","","",""],[7582,7582,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُحَادَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْجَنَّةُ مِائَةُ دَرَجَةٍ مَا بَيْنَ كُلِّ دَرَجَتَيْنِ مِائَةُ عَامٍ ‏","","",""],[7583,7583,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ أَبِي عَمَّارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَطَاعَ الْعَبْدُ رَبَّهُ وَسَيِّدَهُ فَلَهُ أَجْرَانِ ‏","","",""],[7584,7584,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثِرُوا ذِكْرَ هَاذِمِ اللَّذَّاتِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏مُحَمَّدُ بْنُ إِبْرَاهِيمَ ‏ ‏هُوَ ‏ ‏أَبُو بَنِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏بِتِسْعَةٍ وَتِسْعِينَ حَدِيثًا ثُمَّ أَتَمَّهَا بِهَذَا الْحَدِيثِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَمَامَ مِائَةِ حَدِيثٍ ‏","","",""],[7585,7585,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ قُدَامَةَ الْجُمَحِيُّ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ بَكْرِ بْنِ أَبِي الْفُرَاتِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِلْمُنَافِقِينَ عَلَامَاتٍ يُعْرَفُونَ بِهَا تَحِيَّتُهُمْ لَعْنَةٌ وَطَعَامُهُمْ ‏ ‏نُهْبَةٌ ‏ ‏وَغَنِيمَتُهُمْ ‏ ‏غُلُولٌ ‏ ‏وَلَا يَقْرَبُونَ الْمَسَاجِدَ إِلَّا هَجْرًا وَلَا يَأْتُونَ الصَّلَاةَ إِلَّا ‏ ‏دَبْرًا ‏ ‏مُسْتَكْبِرِينَ لَا يَأْلَفُونَ وَلَا يُؤْلَفُونَ ‏ ‏خُشُبٌ ‏ ‏بِاللَّيْلِ ‏ ‏صُخُبٌ ‏ ‏بِالنَّهَارِ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏مَرَّةً ‏ ‏سُخُبٌ ‏ ‏بِالنَّهَارِ ‏","","",""],[7586,7586,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏الْمَعْنَى ‏ ‏أَنَّ النَّاسَ قَالُوا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏هَلْ نَرَى رَبَّنَا عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي الْقَمَرِ لَيْلَةَ الْبَدْرِ قَالُوا لَا يَا رَسُولَ اللَّهِ قَالَ فَهَلْ ‏ ‏تُضَارُّونَ ‏ ‏فِي الشَّمْسِ لَيْسَ دُونَهَا سَحَابٌ قَالُوا لَا قَالَ فَإِنَّكُمْ تَرَوْنَهُ كَذَلِكَ يَجْمَعُ اللَّهُ النَّاسَ يَوْمَ الْقِيَامَةِ فَيُقَالُ مَنْ كَانَ يَعْبُدُ شَيْئًا فَلْيَتَّبِعْهُ فَيَتْبَعُ مَنْ يَعْبُدُ الشَّمْسَ الشَّمْسَ وَيَتْبَعُ مَنْ يَعْبُدُ الْقَمَرَ الْقَمَرَ وَيَتْبَعُ مَنْ يَعْبُدُ ‏ ‏الطَّوَاغِيتَ ‏ ‏الطَّوَاغِيتَ ‏ ‏وَتَبْقَى هَذِهِ الْأُمَّةُ فِيهَا شَافِعُوهَا ‏ ‏أَوْ مُنَافِقُوهَا قَالَ ‏ ‏أَبُو كَامِلٍ ‏ ‏شَكَّ ‏ ‏إِبْرَاهِيمُ ‏ ‏فَيَأْتِيهِمْ اللَّهُ عَزَّ وَجَلَّ فِي صُورَةٍ غَيْرِ صُورَتِهِ الَّتِي يَعْرِفُونَ فَيَقُولُ أَنَا رَبُّكُمْ فَيَقُولُونَ نَعُوذُ بِاللَّهِ مِنْكَ هَذَا مَكَانُنَا حَتَّى يَأْتِيَنَا رَبُّنَا فَإِذَا جَاءَ رَبُّنَا عَرَفْنَاهُ ‏ ‏فَيَأْتِيهِمْ اللَّهُ عَزَّ وَجَلَّ فِي صُورَتِهِ الَّتِي يَعْرِفُونَ فَيَقُولُ أَنَا رَبُّكُمْ فَيَقُولُونَ أَنْتَ رَبُّنَا فَيَتَّبِعُونَهُ وَيُضْرَبُ الصِّرَاطُ بَيْنَ ظَهْرَيْ جَهَنَّمَ فَأَكُونُ أَنَا وَأُمَّتِي أَوَّلَ مَنْ يَجُوزُ وَلَا يَتَكَلَّمُ يَوْمَئِذٍ إِلَّا الرُّسُلُ وَدَعْوَى الرُّسُلِ يَوْمَئِذٍ اللَّهُمَّ سَلِّمْ سَلِّمْ وَفِي جَهَنَّمَ ‏ ‏كَلَالِيبُ ‏ ‏مِثْلُ ‏ ‏شَوْكِ السَّعْدَانِ ‏ ‏هَلْ رَأَيْتُمْ السَّعْدَانَ قَالُوا نَعَمْ يَا رَسُولَ اللَّهِ قَالَ فَإِنَّهَا مِثْلُ ‏ ‏شَوْكِ السَّعْدَانِ ‏ ‏غَيْرَ أَنَّهُ لَا يَعْلَمُ قَدْرَ عِظَمِهَا إِلَّا اللَّهُ تَعَالَى تَخْطَفُ النَّاسَ بِأَعْمَالِهِمْ فَمِنْهُمْ ‏ ‏الْمُوبَقُ ‏ ‏بِعَمَلِهِ ‏ ‏أَوْ قَالَ الْمُوثَقُ بِعَمَلِهِ أَوْ ‏ ‏الْمُخَرْدَلُ ‏ ‏وَمِنْهُمْ ‏ ‏الْمُجَازَى ‏ ‏قَالَ ‏ ‏أَبُو كَامِلٍ ‏ ‏فِي حَدِيثِهِ شَكَّ ‏ ‏إِبْرَاهِيمُ ‏ ‏وَمِنْهُمْ ‏ ‏الْمُخَرْدَلُ ‏ ‏أَوْ ‏ ‏الْمُجَازَى ‏ ‏ثُمَّ يَتَجَلَّى حَتَّى إِذَا فَرَغَ اللَّهُ عَزَّ وَجَلَّ مِنْ الْقَضَاءِ بَيْنَ الْعِبَادِ وَأَرَادَ أَنْ يُخْرِجَ بِرَحْمَتِهِ مَنْ يَقُولُ لَا إِلَهَ إِلَّا اللَّهُ مِنْ أَهْلِ النَّارِ أَمَرَ الْمَلَائِكَةَ أَنْ يُخْرِجُوا مِنْ النَّارِ مَنْ كَانَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا مِمَّنْ أَرَادَ اللَّهُ أَنْ يَرْحَمَهُ مِمَّنْ يَقُولُ لَا إِلَهَ إِلَّا اللَّهُ فَيَعْرِفُونَهُمْ فِي النَّارِ يَعْرِفُونَهُمْ بِأَثَرِ السُّجُودِ تَأْكُلُ النَّارُ ابْنَ ‏ ‏آدَمَ ‏ ‏إِلَّا أَثَرَ السُّجُودِ وَحَرَّمَ اللَّهُ عَزَّ وَجَلَّ عَلَى النَّارِ أَنْ تَأْكُلَ أَثَرَ السُّجُودِ فَيَخْرُجُونَ مِنْ النَّارِ قَدْ ‏ ‏امْتُحِشُوا ‏ ‏فَيُصَبُّ عَلَيْهِمْ مَاءُ الْحَيَاةِ فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ ‏ ‏وَقَالَ ‏ ‏أَبُو كَامِلٍ ‏ ‏الْحَبَّةُ أَيْضًا فِي ‏ ‏حَمِيلِ ‏ ‏السَّيْلِ ‏ ‏وَيَبْقَى رَجُلٌ مُقْبِلٌ بِوَجْهِهِ عَلَى النَّارِ وَهُوَ آخِرُ أَهْلِ الْجَنَّةِ دُخُولًا فَيَقُولُ أَيْ رَبِّ اصْرِفْ وَجْهِي عَنْ النَّارِ فَإِنَّهُ قَدْ ‏ ‏قَشَبَنِي ‏ ‏رِيحُهَا وَأَحْرَقَنِي دُخَانُهَا فَيَدْعُو اللَّهَ مَا شَاءَ أَنْ يَدْعُوَهُ ثُمَّ يَقُولُ اللَّهُ عَزَّ وَجَلَّ هَلْ عَسَيْتَ إِنْ فُعِلَ ذَلِكَ بِكَ أَنْ تَسْأَلَ غَيْرَهُ فَيَقُولُ لَا وَعِزَّتِكَ لَا أَسْأَلُ غَيْرَهُ وَيُعْطِي رَبَّهُ عَزَّ وَجَلَّ مِنْ عُهُودٍ وَمَوَاثِيقَ مَا شَاءَ فَيَصْرِفُ اللَّهُ عَزَّ وَجَلَّ وَجْهَهُ عَنْ النَّارِ فَإِذَا أَقْبَلَ عَلَى الْجَنَّةِ وَرَآهَا سَكَتَ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ ثُمَّ يَقُولُ أَيْ رَبِّ قَرِّبْنِي إِلَى بَابِ الْجَنَّةِ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ لَهُ أَلَسْتَ قَدْ أَعْطَيْتَ عُهُودَكَ وَمَوَاثِيقَكَ أَنْ لَا تَسْأَلَنِي غَيْرَ مَا أَعْطَيْتُكَ وَيْلَكَ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏مَا أَغْدَرَكَ فَيَقُولُ أَيْ رَبِّ فَيَدْعُو اللَّهَ حَتَّى يَقُولَ لَهُ فَهَلْ عَسَيْتَ إِنْ أُعْطِيتَ ذَلِكَ أَنْ تَسْأَلَ غَيْرَهُ فَيَقُولُ لَا وَعِزَّتِكَ لَا أَسْأَلُ غَيْرَهُ فَيُعْطِي ‏ ‏رَبَّهُ عَزَّ وَجَلَّ مَا شَاءَ مِنْ عُهُودٍ وَمَوَاثِيقَ فَيُقَدِّمُهُ إِلَى بَابِ الْجَنَّةِ فَإِذَا قَامَ عَلَى بَابِ الْجَنَّةِ ‏ ‏انْفَهَقَتْ ‏ ‏لَهُ الْجَنَّةُ فَرَأَى مَا فِيهَا مِنْ ‏ ‏الْحَبْرَةِ ‏ ‏وَالسُّرُورِ فَيَسْكُتُ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ ثُمَّ يَقُولُ أَيْ رَبِّ أَدْخِلْنِي الْجَنَّةَ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ لَهُ أَلَيْسَ قَدْ أَعْطَيْتَ عُهُودَكَ وَمَوَاثِيقَكَ أَنْ لَا تَسْأَلَنِي غَيْرَ مَا أَعْطَيْتُكَ وَيْلَكَ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏مَا أَغْدَرَكَ فَيَقُولُ أَيْ رَبِّ لَا أَكُونُ أَشْقَى خَلْقِكَ فَلَا يَزَالُ يَدْعُو اللَّهَ حَتَّى يَضْحَكَ اللَّهُ مِنْهُ فَإِذَا ضَحِكَ اللَّهُ عَزَّ وَجَلَّ مِنْهُ قَالَ ادْخُلْ الْجَنَّةَ فَإِذَا دَخَلَهَا قَالَ اللَّهُ عَزَّ وَجَلَّ لَهُ ‏ ‏تَمَنَّهْ فَيَسْأَلُ رَبَّهُ عَزَّ وَجَلَّ ‏ ‏وَيَتَمَنَّى حَتَّى إِنَّ اللَّهَ عَزَّ وَجَلَّ لَيُذَكِّرُهُ يَقُولُ مِنْ كَذَا وَكَذَا حَتَّى إِذَا انْقَطَعَتْ بِهِ الْأَمَانِيُّ قَالَ اللَّهُ عَزَّ وَجَلَّ لَهُ لَكَ ذَلِكَ وَمِثْلُهُ مَعَهُ ‏ ‏قَالَ ‏ ‏عَطَاءُ بْنُ يَزِيدَ ‏ ‏وَأَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏لَا يَرُدُّ عَلَيْهِ مِنْ حَدِيثِهِ شَيْئًا حَتَّى إِذَا حَدَّثَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ لِذَلِكَ الرَّجُلِ وَمِثْلُهُ مَعَهُ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَعَشَرَةُ أَمْثَالِهِ مَعَهُ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏مَا حَفِظْتُ إِلَّا قَوْلَهُ ذَلِكَ لَكَ وَمِثْلُهُ مَعَهُ قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَشْهَدُ أَنِّي حَفِظْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوْلَهُ فِي ذَلِكَ الرَّجُلِ لَكَ عَشَرَةُ أَمْثَالِهِ ‏ ‏قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏وَذَلِكَ الرَّجُلُ آخِرُ أَهْلِ الْجَنَّةِ دُخُولًا ‏","","",""],[7587,7587,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَيَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَهَذَا حَدِيثُ ‏ ‏سُلَيْمَانَ الْهَاشِمِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَسِيدِ بْنِ جَارِيَةَ الثَّقَفِيِّ ‏ ‏حَلِيفِ ‏ ‏بَنِي زُهْرَةَ ‏ ‏وَكَانَ مِنْ أَصْحَابِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشَرَةَ ‏ ‏رَهْطٍ ‏ ‏عَيْنًا ‏ ‏وَأَمَّرَ عَلَيْهِمْ ‏ ‏عَاصِمَ بْنَ ثَابِتِ بْنِ أَبِي الْأَقْلَحِ ‏ ‏جَدَّ ‏ ‏عَاصِمِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏فَانْطَلَقُوا حَتَّى إِذَا كَانُوا ‏ ‏بِالْهَدَّةِ ‏ ‏بَيْنَ ‏ ‏عُسْفَانَ ‏ ‏وَمَكَّةَ ‏ ‏ذُكِرُوا لِحَيٍّ ‏ ‏مِنْ ‏ ‏هُذَيْلٍ ‏ ‏يُقَالُ لَهُمْ ‏ ‏بَنُو لِحْيَانَ ‏ ‏فَنَفَرُوا لَهُمْ بِقَرِيبٍ مِنْ مِائَةِ رَجُلٍ ‏ ‏رَامٍ ‏ ‏فَاقْتَصُّوا ‏ ‏آثَارَهُمْ حَتَّى وَجَدُوا مَأْكَلَهُمْ التَّمْرَ فِي مَنْزِلٍ نَزَلُوهُ قَالُوا نَوَى تَمْرِ ‏ ‏يَثْرِبَ ‏ ‏فَاتَّبَعُوا آثَارَهُمْ فَلَمَّا أُخْبِرَ بِهِمْ ‏ ‏عَاصِمٌ ‏ ‏وَأَصْحَابُهُ لَجَئُوا إِلَى ‏ ‏فَدْفَدٍ ‏ ‏فَأَحَاطَ بِهِمْ الْقَوْمُ فَقَالُوا لَهُمْ انْزِلُوا وَأَعْطُونَا بِأَيْدِيكُمْ وَلَكُمْ الْعَهْدُ وَالْمِيثَاقُ أَنْ لَا نَقْتُلَ مِنْكُمْ أَحَدًا فَقَالَ ‏ ‏عَاصِمُ بْنُ ثَابِتٍ ‏ ‏أَمِيرُ الْقَوْمِ أَمَّا أَنَا وَاللَّهِ لَا أَنْزِلُ فِي ذِمَّةِ كَافِرٍ اللَّهُمَّ أَخْبِرْ عَنَّا نَبِيَّكَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَمَوْهُمْ بِالنَّبْلِ فَقَتَلُوا ‏ ‏عَاصِمًا ‏ ‏فِي سَبْعَةٍ وَنَزَلَ إِلَيْهِمْ ثَلَاثَةُ ‏ ‏نَفَرٍ ‏ ‏عَلَى الْعَهْدِ وَالْمِيثَاقِ مِنْهُمْ ‏ ‏خُبَيْبٌ الْأَنْصَارِيُّ ‏ ‏وَزَيْدُ بْنُ الدَّثِنَةِ ‏ ‏وَرَجُلٌ آخَرُ فَلَمَّا تَمَكَّنُوا مِنْهُمْ أَطْلَقُوا أَوْتَارَ ‏ ‏قِسِيِّهِمْ ‏ ‏فَرَبَطُوهُمْ بِهَا فَقَالَ الرَّجُلُ الثَّالِثُ هَذَا أَوَّلُ الْغَدْرِ وَاللَّهِ لَا أَصْحَبُكُمْ إِنَّ لِي بِهَؤُلَاءِ لَأُسْوَةً يُرِيدُ الْقَتْلَ فَجَرَّرُوهُ وَعَالَجُوهُ فَأَبَى أَنْ يَصْحَبَهُمْ فَقَتَلُوهُ فَانْطَلَقُوا ‏ ‏بِخُبَيْبٍ ‏ ‏وَزَيْدِ بْنِ الدَّثِنَةِ ‏ ‏حَتَّى بَاعُوهُمَا ‏ ‏بِمَكَّةَ ‏ ‏بَعْدَ وَقْعَةِ ‏ ‏بَدْرٍ ‏ ‏فَابْتَاعَ ‏ ‏بَنُو الْحَارِثِ بْنِ عَامِرِ بْنِ نَوْفَلِ بْنِ عَبْدِ مَنَافٍ ‏ ‏خُبَيْبًا ‏ ‏وَكَانَ ‏ ‏خُبَيْبٌ ‏ ‏هُوَ قَتَلَ ‏ ‏الْحَارِثَ بْنَ عَامِرِ بْنِ نَوْفَلٍ ‏ ‏يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَلَبِثَ ‏ ‏خُبَيْبٌ ‏ ‏عِنْدَهُمْ أَسِيرًا حَتَّى أَجْمَعُوا قَتْلَهُ فَاسْتَعَارَ مِنْ بَعْضِ بَنَاتِ ‏ ‏الْحَارِثِ ‏ ‏مُوسَى يَسْتَحِدُّ بِهَا لِلْقَتْلِ فَأَعَارَتْهُ إِيَّاهَا ‏ ‏فَدَرَجَ ‏ ‏بُنَيٌّ لَهَا قَالَتْ وَأَنَا غَافِلَةٌ حَتَّى أَتَاهُ فَوَجَدْتُهُ يُجْلِسُهُ عَلَى فَخِذِهِ وَالْمُوسَى بِيَدِهِ قَالَتْ فَفَزِعْتُ فَزْعَةً عَرَفَهَا ‏ ‏خُبَيْبٌ ‏ ‏قَالَ أَتَخْشَيْنَ أَنِّي أَقْتُلُهُ مَا كُنْتُ لِأَفْعَلَ فَقَالَتْ وَاللَّهِ مَا رَأَيْتُ أَسِيرًا قَطُّ خَيْرًا مِنْ ‏ ‏خُبَيْبٍ ‏ ‏قَالَتْ وَاللَّهِ لَقَدْ وَجَدْتُهُ يَوْمًا يَأْكُلُ قِطْفًا مِنْ عِنَبٍ فِي يَدِهِ وَإِنَّهُ لَمُوثَقٌ فِي الْحَدِيدِ وَمَا ‏ ‏بِمَكَّةَ ‏ ‏مِنْ ثَمَرَةٍ وَكَانَتْ تَقُولُ إِنَّهُ لَرِزْقٌ رَزَقَهُ اللَّهُ ‏ ‏خُبَيْبًا ‏ ‏فَلَمَّا خَرَجُوا بِهِ مِنْ ‏ ‏الْحَرَمِ ‏ ‏لِيَقْتُلُوهُ فِي الْحِلِّ قَالَ لَهُمْ ‏ ‏خُبَيْبٌ ‏ ‏دَعُونِي أَرْكَعْ رَكْعَتَيْنِ فَتَرَكُوهُ فَرَكَعَ رَكْعَتَيْنِ ثُمَّ قَالَ وَاللَّهِ لَوْلَا أَنْ تَحْسِبُوا أَنَّ مَا بِي ‏ ‏جَزَعًا ‏ ‏مِنْ الْقَتْلِ لَزِدْتُ اللَّهُمَّ أَحْصِهِمْ عَدَدًا وَاقْتُلْهُمْ بَدَدًا وَلَا تُبْقِ مِنْهُمْ أَحَدًا ‏ ‏فَلَسْتُ أُبَالِي حِينَ أُقْتَلُ مُسْلِمًا ‏ ‏عَلَى أَيِّ جَنْبٍ كَانَ لِلَّهِ مَصْرَعِي ‏ ‏وَذَلِكَ فِي ذَاتِ الْإِلَهِ وَإِنْ يَشَأْ ‏ ‏يُبَارِكْ عَلَى أَوْصَالِ ‏ ‏شِلْوٍ ‏ ‏مُمَزَّعِ ‏ ‏ثُمَّ قَامَ إِلَيْهِ ‏ ‏أَبُو سِرْوَعَةَ عُقْبَةُ بْنُ الْحَارِثِ ‏ ‏فَقَتَلَهُ وَكَانَ ‏ ‏خُبَيْبٌ ‏ ‏هُوَ سَنَّ لِكُلِّ مُسْلِمٍ قُتِلَ صَبْرًا الصَّلَاةَ وَاسْتَجَابَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏لِعَاصِمِ بْنِ ثَابِتٍ ‏ ‏يَوْمَ أُصِيبَ فَأَخْبَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصْحَابَهُ يَوْمَ أُصِيبُوا خَبَرَهُمْ وَبَعَثَ نَاسٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏إِلَى ‏ ‏عَاصِمِ بْنِ ثَابِتٍ ‏ ‏حِينَ حُدِّثُوا أَنَّهُ قُتِلَ ‏ ‏لِيُؤْتَى بِشَيْءٍ مِنْهُ يُعْرَفُ وَكَانَ قَتَلَ رَجُلًا مِنْ عُظَمَائِهِمْ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَبَعَثَ اللَّهُ عَزَّ وَجَلَّ عَلَى ‏ ‏عَاصِمٍ ‏ ‏مِثْلَ الظُّلَّةِ مِنْ ‏ ‏الدَّبْرِ ‏ ‏فَحَمَتْهُ مِنْ رُسُلِهِمْ فَلَمْ يَقْدِرُوا عَلَى أَنْ يَقْطَعُوا مِنْهُ شَيْئًا ‏","","",""],[7588,7588,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عُبَيْدٍ أَبِي مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي جَنَازَةٍ ‏ ‏فَأَمْشِي فَإِذَا مَشَيْتُ سَبَقَنِي فَأُهَرْوِلُ فَأَسْبِقُهُ فَالْتَفَتَ رَجُلٌ إِلَى جَنْبِي فَقَالَ ‏ ‏تُطْوَى لَهُ الْأَرْضُ وَخَلِيلِ ‏ ‏إِبْرَاهِيمَ ‏","","",""],[7589,7589,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نُهِيَ عَنْ ‏ ‏الِاخْتِصَارِ فِي الصَّلَاةِ فَقُلْنَا ‏ ‏لِهِشَامٍ ‏ ‏ذَكَرَهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بِرَأْسِهِ أَيْ نَعَمْ ‏","","",""],[7590,7590,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ بْنُ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الْجَبَّارِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الرَّحِمُ شِجْنَةٌ مِنْ الرَّحْمَنِ عَزَّ وَجَلَّ تَجِيءُ يَوْمَ الْقِيَامَةِ تَقُولُ يَا رَبِّ قُطِعْتُ يَا رَبِّ ظُلِمْتُ يَا رَبِّ أُسِيءَ إِلَيَّ ‏","","",""],[7591,7591,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ إِنِّي إِذَا رَأَيْتُكَ طَابَتْ نَفْسِي وَقَرَّتْ عَيْنِي فَأَنْبِئْنِي عَنْ كُلِّ شَيْءٍ فَقَالَ كُلُّ شَيْءٍ خُلِقَ مِنْ مَاءٍ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أَنْبِئْنِي عَنْ أَمْرٍ إِذَا أَخَذْتُ بِهِ دَخَلْتُ الْجَنَّةَ قَالَ ‏ ‏أَفْشِ السَّلَامَ وَأَطْعِمْ الطَّعَامَ وَصِلْ الْأَرْحَامَ وَقُمْ بِاللَّيْلِ وَالنَّاسُ نِيَامٌ ثُمَّ ادْخُلْ الْجَنَّةَ بِسَلَامٍ ‏","","",""],[7592,7592,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَدْخُلُ أَهْلُ الْجَنَّةِ الْجَنَّةَ ‏ ‏جُرْدًا ‏ ‏مُرْدًا ‏ ‏بِيضًا ‏ ‏جِعَادًا ‏ ‏مُكَحَّلِينَ أَبْنَاءَ ثَلَاثٍ وَثَلَاثِينَ عَلَى خَلْقِ ‏ ‏آدَمَ ‏ ‏سِتُّونَ ذِرَاعًا فِي عَرْضِ سَبْعِ أَذْرُعٍ ‏","","",""],[7593,7593,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عِسْلِ بْنِ سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏السَّدْلِ ‏ ‏فِي الصَّلَاةِ ‏","","",""],[7594,7594,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْأَرْوَاحُ جُنُودٌ مُجَنَّدَةٌ فَمَا تَعَارَفَ مِنْهَا ائْتَلَفَ وَمَا تَنَاكَرَ مِنْهَا اخْتَلَفَ ‏","","",""],[7595,7595,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَانَتْ لَهُ امْرَأَتَانِ يَمِيلُ لِإِحْدَاهُمَا عَلَى الْأُخْرَى جَاءَ يَوْمَ الْقِيَامَةِ يَجُرُّ أَحَدَ ‏ ‏شِقَّيْهِ ‏ ‏سَاقِطًا ‏ ‏أَوْ مَائِلًا شَكَّ ‏ ‏يَزِيدُ ‏","","",""],[7596,7596,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏وَعَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَخْرُجُ الدَّابَّةُ وَمَعَهَا عَصَا ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَخَاتَمُ ‏ ‏سُلَيْمَانَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَتَخْطِمُ ‏ ‏الْكَافِرَ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَنْفَ الْكَافِرِ ‏ ‏بِالْخَاتَمِ ‏ ‏وَتَجْلُو وَجْهَ الْمُؤْمِنِ بِالْعَصَا حَتَّى إِنَّ أَهْلَ ‏ ‏الْخِوَانِ ‏ ‏لَيَجْتَمِعُونَ عَلَى ‏ ‏خِوَانِهِمْ ‏ ‏فَيَقُولُ هَذَا يَا مُؤْمِنُ وَيَقُولُ هَذَا يَا كَافِرُ ‏","","",""],[7597,7597,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏أَوَى ‏ ‏أَحَدُكُمْ إِلَى فِرَاشِهِ فَلْيَنْفُضْهُ بِدَاخِلَةِ ‏ ‏إِزَارِهِ ‏ ‏فَإِنَّهُ لَا يَدْرِي مَا حَدَثَ بَعْدَهُ وَإِذَا وَضَعَ جَنْبَهُ فَلْيَقُلْ بِاسْمِكَ اللَّهُمَّ وَضَعْتُ جَنْبِي وَبِكَ أَرْفَعُهُ اللَّهُمَّ إِنْ أَمْسَكْتَ نَفْسِي فَاغْفِرْ لَهَا وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ ‏","","",""],[7598,7598,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الرَّبِيعُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَشْكُرُ اللَّهَ مَنْ لَا يَشْكُرُ النَّاسَ ‏","","",""],[7599,7599,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ اطَّلَعَ عَلَى أَهْلِ ‏ ‏بَدْرٍ ‏ ‏فَقَالَ اعْمَلُوا مَا شِئْتُمْ فَقَدْ غَفَرْتُ لَكُمْ ‏","","",""],[7600,7600,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ الْمَاجِشُونِ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَجُلٌ ‏ ‏بِفَلَاةٍ ‏ ‏مِنْ الْأَرْضِ فَسَمِعَ صَوْتًا فِي سَحَابَةٍ اسْقِ حَدِيقَةَ فُلَانٍ فَتَنَحَّى ذَلِكَ السَّحَابُ فَأَفْرَغَ مَاءَهُ فِي ‏ ‏حَرَّةٍ ‏ ‏فَانْتَهَى إِلَى ‏ ‏الْحَرَّةِ ‏ ‏فَإِذَا هُوَ فِي ‏ ‏أَذْنَابِ ‏ ‏شِرَاجٍ ‏ ‏وَإِذَا ‏ ‏شَرْجَةٌ ‏ ‏مِنْ تِلْكَ ‏ ‏الشِّرَاجِ ‏ ‏قَدْ اسْتَوْعَبَتْ ذَلِكَ الْمَاءَ كُلَّهُ فَتَبِعَ الْمَاءَ فَإِذَا رَجُلٌ قَائِمٌ فِي حَدِيقَتِهِ يُحَوِّلُ الْمَاءَ بِمِسْحَاتِهِ فَقَالَ لَهُ يَا عَبْدَ اللَّهِ مَا اسْمُكَ قَالَ فُلَانٌ ‏ ‏بِالِاسْمِ الَّذِي سَمِعَ فِي السَّحَابَةِ فَقَالَ لَهُ يَا عَبْدَ اللَّهِ لِمَ تَسْأَلُنِي عَنْ اسْمِي قَالَ إِنِّي سَمِعْتُ صَوْتًا فِي السَّحَابِ الَّذِي هَذَا مَاؤُهُ يَقُولُ اسْقِ حَدِيقَةَ فُلَانٍ لِاسْمِكَ فَمَا تَصْنَعُ فِيهَا قَالَ أَمَّا إِذَا قُلْتَ هَذَا فَإِنِّي أَنْظُرُ إِلَى مَا خَرَجَ مِنْهَا فَأَتَصَدَّقُ بِثُلُثِهِ وَآكُلُ أَنَا وَعِيَالِي ثُلُثَهُ وَأَرُدُّ فِيهَا ثُلُثَهُ ‏","","",""]];
